insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('marine', 'advanced', 'module', 'm01-the-shore-base-as-a-queue', 1, 'The Ekene supply base states 2 fixed hours a call, 60 lifts at 12 an hour and 900 m3 of bulk at 150 m3 an hour, with the lifts and the bulk at the same time. What service time does the engine return for one call?', '["13.000000 hours, the fixed hours plus the lift hours plus the bulk hours taken one after another", "6.000000 hours, the bulk hours alone, because the pumping outlasts the crane work", "8.000000 hours, the fixed hours plus the larger of the lift hours and the bulk hours", "5.000000 hours, the lift hours alone, as though the crane were the berth''s only task"]'::jsonb, 2, 'With the concurrent choice true, the engine adds the fixed hours to the larger of the lift hours (60 over 12 is 5.000000) and the bulk hours (900 over 150 is 6.000000): 2 plus 6 gives 8.000000 hours. 13.000000 is the service when the lifts and the bulk run one after the other; 6.000000 and 5.000000 each drop the fixed hours and one of the two terms.'),
  ('marine', 'advanced', 'module', 'm01-the-shore-base-as-a-queue', 2, 'The Ekene base is run with the lifts first and the bulk after them (concurrent false), still 2 berths and 3.2 arrivals a day over 24 working hours. What berth utilisation does the engine return?', '["0.866667, an offered load of 1.733333 spread over the 2 berths", "0.533333, the figure with the lifts and the bulk alongside", "1.733333, the offered load before it is spread over berths", "0.711111, which is what the three berths carry on a twelve-hour working day"]'::jsonb, 0, 'One after the other, the service is 2 plus 5 plus 6, 13.000000 hours; 0.133333 arrivals an hour times 13.000000 is an offered load of 1.733333, and over 2 berths the berth utilisation is 0.866667. 0.533333 belongs to the 8-hour concurrent service; 1.733333 is the offered load before it is spread over the berths; 0.711111 is the three-berth base on a twelve-hour day.'),
  ('marine', 'advanced', 'module', 'm01-the-shore-base-as-a-queue', 3, 'On the working-hour clock, what arrivals an hour does the engine return for the Ekene base, which takes 3.2 arrivals a day over a 24-hour working day?', '["0.266667 an hour, the rate the same 3.2 arrivals give over a twelve-hour working day", "1.066667 an hour, the arrivals an hour already multiplied by the 8-hour service", "0.533333 an hour, the busy share of each berth''s hours", "0.133333 an hour, the arrivals a day over the working hours a day"]'::jsonb, 3, 'Arrivals an hour are the stated arrivals a day over the stated working hours a day: 3.2 over 24 is 0.133333. 0.266667 is the same 3.2 over a 12-hour day; 1.066667 is the offered load, the arrivals an hour times the 8.000000-hour service; 0.533333 is the berth utilisation.'),
  ('marine', 'advanced', 'module', 'm01-the-shore-base-as-a-queue', 4, 'Shorten the Ekene quay''s working day to 12 hours and give it a third berth, keeping the 3.2 daily arrivals and the 8-hour concurrent calls. What berth utilisation results?', '["0.355556, the three-berth figure the same base returns on a 24-hour working day", "0.711111, an offered load of 2.133333 carried by the 3 berths", "2.133333, the offered load, taken as though it were already a berth utilisation", "0.533333, the figure the two-berth base returns on a 24-hour working day"]'::jsonb, 1, 'Over 12 working hours the 3.2 arrivals come at 0.266667 an hour; times 8.000000 hours the offered load is 2.133333, and over 3 berths the berth utilisation is 0.711111. 0.355556 is three berths on the 24-hour clock; 2.133333 is the load before it is spread; 0.533333 is the two-berth base on 24 hours. Halving the working day doubles the arrivals an hour.'),
  ('marine', 'advanced', 'module', 'm01-the-shore-base-as-a-queue', 5, 'What does the engine call the offered load at the base, and what is it for the Ekene base with its 8-hour calls?', '["The arrivals an hour times the service time: 1.066667 berth-hours of work in each working hour", "The offered load over the berths: 0.533333, the busy share of each berth''s working hours", "The mean number of vessels waiting for a berth at any moment: 0.424017 on two berths", "The vessels at the base on average, queue and berths together: 1.490683 on two berths"]'::jsonb, 0, 'The offered load is the arrivals an hour times the service time, 0.133333 times 8.000000, which is 1.066667: a little more than one berth''s work arrives every working hour. 0.533333 is that load over the 2 berths, the berth utilisation; 0.424017 is the mean queue; 1.490683 is the mean in the system.'),
  ('marine', 'advanced', 'module', 'm01-the-shore-base-as-a-queue', 6, 'The Ekene base is stated with 3 berths and every other input held. Which pair of figures does the engine return?', '["An offered load of 1.066667 and a berth utilisation of 0.533333", "An offered load of 2.133333 and a berth utilisation of 0.711111", "An offered load still at 1.066667, with a berth utilisation of 0.355556", "An offered load cut to 0.355556 and a berth utilisation that follows it at 0.266667"]'::jsonb, 2, 'The offered load is the arrivals an hour times the service time, so a third berth does not move it from 1.066667; what moves is the share each berth carries, 1.066667 over 3, which is 0.355556. 0.533333 is the two-berth figure; 2.133333 and 0.711111 belong to the twelve-hour day; 0.266667 is the berth utilisation at four berths.'),
  ('marine', 'advanced', 'module', 'm01-the-shore-base-as-a-queue', 7, 'The Ekene base (3.2 arrivals a day, 24 working hours, 8-hour calls) is handed to the engine with 1 berth. What comes back?', '["A result with a very long mean wait, since a berth utilisation of 1.066667 is only a little above one", "A refusal on arrivalsPerDay: at most 2.999999 a day for a steady state, the berth utilisation being 1.066667", "Returned figures with a reason saying the single berth is overloaded, and the wait it would face", "Refused on berths by name, because the engine accepts no base with fewer than 2 berths at all"]'::jsonb, 1, 'With one berth the berth utilisation would be 1.066667, and at or above 1 no steady state exists, so the engine refuses. In its own words: "arrivalsPerDay must be at most 2.999999 (rounded down at the sixth decimal so that it is accepted) for a steady state with 1 berth: the berth utilisation must stay below 1, so arrivals a day must stay below berths x working hours a day / service hours = 3; got 3.2, a berth utilisation of 1.066667". A refusal returns no figures, so no wait and no reason come back; berths from 1 to 100 are accepted.'),
  ('marine', 'advanced', 'module', 'm01-the-shore-base-as-a-queue', 8, 'In the engine''s refusal of the one-berth Ekene base, the exact bound is 3 arrivals a day. How is that bound built?', '["The arrivals an hour times the working hours, less the vessels already queued at the quay", "The largest arrivals a day at which the mean wait stays inside one working day of 24 hours", "The number of vessels one berth can hold alongside at once", "The berths times the working hours a day over the service hours: 1 times 24 over 8"]'::jsonb, 3, 'The berth utilisation must stay below 1, which caps the arrivals a day below berths x working hours a day / service hours: 1 times 24 over 8 is 3. The bound is set by saturation alone; it has nothing to do with a target wait or with how many vessels lie alongside, and the queue does not enter it.'),
  ('marine', 'advanced', 'module', 'm01-the-shore-base-as-a-queue', 9, 'A base is stated so that its berth utilisation comes to 0.999500. What kind of answer does the engine give?', '["A refusal on arrivalsPerDay, since any berth utilisation that close to 1 has no steady state", "A result whose mean wait is held at one working day, the longest figure the engine reports", "A result, since below 1 a steady state exists, with a mean wait that runs very long", "A reason with no figures, saying that the berths are saturated and naming the bound"]'::jsonb, 2, 'The steady state needs a berth utilisation strictly below 1, and 0.999500 is below it, so the engine returns its figures: on that case a mean wait of 999.250063 hours and a mean queue of 1997.500875. The engine holds no cap on the wait, and a figure at 1 or above is refused with the bound printed.'),
  ('marine', 'advanced', 'module', 'm01-the-shore-base-as-a-queue', 10, 'A shore base call states every input except whether the lifts and the bulk run at the same time. What does the engine return?', '["service.concurrent must be true (lifts and bulk at the same time) or false (one after the other); there is no default; got nothing", "A result with the lifts and the bulk run one after the other, the slower of the two choices, and a line in its basis saying so", "service must give a service time above 0 hours (fixed hours, lifts or bulk); got 0", "Figures computed with the lifts and bulk alongside, the choice that gives the shorter service time, and a note of the choice"]'::jsonb, 0, 'The concurrent choice is a required input with no default, because whether a base can crane and pump at once depends on crews, hoses and safety rules the engine cannot see. The engine''s own words are the key. The "service must give a service time above 0 hours" message belongs to a call whose terms add to no time at all, and no service time can be built from it; the engine never picks either choice for the planner.'),
  ('marine', 'advanced', 'module', 'm01-the-shore-base-as-a-queue', 11, 'A call states a working day of 25 hours for the base. What does the engine return, in its own words?', '["A result on the 24-hour clock with the extra hour dropped and a note in the basis", "Figures on a 25-hour clock, the arrivals an hour taken over the 25 hours as typed", "berths must be a whole number from 1 to 100; got 25", "workingHoursPerDay must be a number above 0 and at most 24; got 25"]'::jsonb, 3, 'The working day is a number above 0 and at most 24, and the engine refuses anything else by name, verbatim: "workingHoursPerDay must be a number above 0 and at most 24; got 25". It neither trims the figure to 24 nor runs on it, and the field it names is the working day. The berths message would read the 25 as a berth count, which no field of this call is.'),
  ('marine', 'advanced', 'module', 'm01-the-shore-base-as-a-queue', 12, 'A call states 0 lifts an hour for the crane at the base, with lifts to make. What does the engine return?', '["service must give a service time above 0 hours (fixed hours, lifts or bulk); got 0", "A refusal naming service.liftsPerHour, the lift rate, which has to be above 0", "A result with the lift hours read as 0, so the call is the fixed hours and the bulk", "A result whose service time has no limit, followed by a refusal of the arrivals"]'::jsonb, 1, 'A rate of zero would make the lift hours infinite, and the engine refuses the rate by name, verbatim: "service.liftsPerHour must be a finite number above 0; got 0". The "service must give a service time above 0 hours" message is the refusal of a call whose terms add to no time at all, a different case; no result is returned either way.'),
  ('marine', 'advanced', 'module', 'm01-the-shore-base-as-a-queue', 13, 'A planner types the crane rate at the base under the key service.craneRate. What does the engine do with it?', '["Drops the unknown key without a word and runs the call on the service terms it does read, so the stated crane rate is quietly lost", "Reads it as the lifts an hour, since the crane is the plant that lifts the deck cargo, and prints the mapping in the basis", "Refuses it by name and lists the keys of service it does read: fixedHours, lifts, liftsPerHour, bulkM3, bulkM3PerHour, concurrent", "Runs the call as typed and adds a line to its basis saying that one key of service was read as a comment and ignored"]'::jsonb, 2, 'Every call refuses an input key the function does not read, at every level, naming the key, its path and the accepted keys. Verbatim: "service.craneRate is not an accepted key; the accepted keys of service are fixedHours, lifts, liftsPerHour, bulkM3, bulkM3PerHour, concurrent". A misspelt key is refused; the engine drops no key silently and maps none to another input.'),
  ('marine', 'advanced', 'module', 'm01-the-shore-base-as-a-queue', 14, 'Why does the engine count the queue at the base on the working hour?', '["A base that closes holds its arrivals until it opens, so the queue forms in the hours the berths work", "Vessels reach the base only in working hours, so any vessel arriving at night is dropped from the count", "Erlang''s C formula needs whole working days as its unit of time, so the working hour is the smallest unit", "So that every wait comes out in calendar days, the unit in which vessel charters are billed"]'::jsonb, 0, 'Arrivals an hour are the arrivals a day over the working hours a day, and every time the queue returns is in working hours: counting the closed hours would spread the same vessels over hours in which no berth serves anyone. No arrival is dropped, the formula takes any unit of time, and the engine prices no charter.'),
  ('marine', 'advanced', 'module', 'm01-the-shore-base-as-a-queue', 15, 'On the Ekene base as M/M/c, the engine returns a berth utilisation of 0.533333. What does that figure tell a planner?', '["Roughly half of the arriving vessels will find both berths taken and wait for one to come free", "How busy the berths are, and that a steady state exists; how often and how long vessels wait depend on the model", "That an arriving vessel spends about half of its time at the base waiting in the queue for a berth", "That the base could take about half as many arrivals again before a vessel first had to wait"]'::jsonb, 1, 'The berth utilisation is the offered load over the berths, the share of each berth''s working hours spent serving. It says the base is below saturation and how busy it is; the probability of waiting (0.371014 as M/M/c) and the mean wait come from the model. Vessels can wait at any utilisation above zero.'),
  ('marine', 'advanced', 'module', 'm02-erlang-c-and-mmc', 1, 'The Ekene base runs as M/M/c with 2 berths, 3.2 arrivals a day over 24 working hours and an 8-hour concurrent service. What probability of waiting does the engine return?', '["0.533333, the berth utilisation read as a share of arrivals", "0.371014, Erlang''s C figure for an offered load of 1.066667 on 2 berths", "0.106417, which is the figure the same base returns once a third berth is stated", "0.424017, the mean number of vessels in the queue, read as though it were a share"]'::jsonb, 1, 'The delay probability is Erlang''s C formula (Adan and Resing, Queueing Systems, 26 March 2015, eq. 5.1; Iversen, Teletraffic Engineering Handbook, draft of 20 June 2001, s. 12.2): 0.371014 on the Ekene base. 0.533333 is the berth utilisation, which is a different quantity; 0.106417 is the three-berth probe; 0.424017 is the mean queue.'),
  ('marine', 'advanced', 'module', 'm02-erlang-c-and-mmc', 2, 'How does the engine compute Erlang''s C delay probability for a base with many berths?', '["By writing the factorials and powers of the offered load out directly, just as eq. 5.1 is set down on the page", "By a seeded Monte Carlo of arrivals and service times drawn through lib/stats on the stated seed and draws", "By looking the row up in Adan and Resing''s Tables 5.1 and 5.2 and interpolating between the printed rows", "By the stable Erlang B recursion, one berth at a time, then turning the B figure into the delay probability"]'::jsonb, 3, 'The engine follows Adan and Resing, s. 11.3 (recursion 11.3 and remark 11.3.2): Erlang''s B figure is built one berth at a time from the one before, and the delay probability follows from it. Written out directly, the factorials and powers outgrow what a computer holds long before a large base; the one sampler in the engine serves fleetVariability alone; the published tables are checks the engine reproduces, and it looks nothing up.'),
  ('marine', 'advanced', 'module', 'm02-erlang-c-and-mmc', 3, 'Eq. 5.2 of Adan and Resing takes PiW = 0.371014 and rho = 0.533333 from the two-berth Ekene quay. What mean queue results, as the engine returns it?', '["0.424017 vessels, the probability of waiting times rho over 1 less rho", "0.371014 vessels, the probability of waiting read as a count", "1.490683 vessels, which counts the vessels alongside the berths as well as those queued", "3.180124 vessels, the mean wait in hours read as a count"]'::jsonb, 0, 'Adan and Resing''s eq. 5.2 gives E(Lq) = PiW rho / (1 - rho): 0.371014 times 0.533333, over 1 less 0.533333, gives 0.424017 as the engine returns it. 1.490683 is the mean in the system, the queue plus the offered load; 0.371014 is a probability; 3.180124 is the mean wait in hours.'),
  ('marine', 'advanced', 'module', 'm02-erlang-c-and-mmc', 4, 'On the same Ekene base as M/M/c, which mean wait in hours does the engine return by eq. 5.3, E(W) = PiW S / (c (1 - rho))?', '["11.180124 hours, which is the wait with the 8.000000-hour service added on top of it", "1.665786 hours, the M/D/c figure for the same base (the Cosmetatos approximation)", "3.180124 hours in the queue, on the working-hour clock, before a berth comes free", "0.440347 hours, the figure the same inputs return when a third berth is stated"]'::jsonb, 2, 'With PiW 0.371014, S 8.000000 hours, c 2 and rho 0.533333, eq. 5.3 gives 3.180124 hours, which is the course''s wait: the mean time in the queue on the working-hour clock. 11.180124 is the mean time at the base; 1.665786 is the M/D/c wait (the Cosmetatos approximation); 0.440347 is the three-berth probe.'),
  ('marine', 'advanced', 'module', 'm02-erlang-c-and-mmc', 5, 'A vessel at the two-berth Ekene quay waits 3.180124 hours on average under M/M/c and is then served for 8 hours. How long is its mean stay at the base?', '["3.180124 hours, since the wait already covers the whole stay at the quay for a vessel", "8.000000 hours, the service time of one call alone", "1.490683 hours, the mean in the system read across as a time in hours at the base", "11.180124 hours, the mean wait plus the service time of one call"]'::jsonb, 3, 'The engine''s mean time at the base is the wait plus the service: 3.180124 plus 8.000000 is 11.180124 hours. The course keeps the words apart: the wait is the time in the queue, and the time at the base adds the service. 1.490683 is the mean in the system, a count of vessels.'),
  ('marine', 'advanced', 'module', 'm02-erlang-c-and-mmc', 6, 'On the Ekene base as M/M/c, the mean queue is 0.424017 and the offered load 1.066667. What mean in the system does the engine return?', '["0.424017 vessels, the queue alone counted as the system", "1.490683 vessels, the mean queue plus the vessels at the berths", "1.066667 vessels, the offered load alone, the vessels at the berths at any moment", "0.533333 vessels, the berth utilisation read as a count"]'::jsonb, 1, 'The mean in the system is the mean queue plus the offered load, since the vessels being served average the arrivals an hour times the service time: 0.424017 plus 1.066667 is 1.490683. The other three are each one part of it, or the berth utilisation.'),
  ('marine', 'advanced', 'module', 'm02-erlang-c-and-mmc', 7, 'A planner checks the Ekene M/M/c figures by Little''s law (Adan and Resing, s. 3.4). Which product should reproduce the engine''s mean queue of 0.424017?', '["The arrivals an hour, 0.133333, times the mean wait of 3.180124 hours", "The berth utilisation, 0.533333, times the mean time at the base of 11.180124 hours", "The arrivals a day, 3.2, times the mean wait in working days", "The probability of waiting, 0.371014, times 8.000000 hours"]'::jsonb, 0, 'Little''s law makes the mean number in any part of the base the arrivals an hour times the mean time spent in that part; for the queue that is 0.133333 times 3.180124, which gives 0.424017. The arrivals and the time must be on the same clock, the working hour. The other products mix a share with a time or a daily count with an hourly one.'),
  ('marine', 'advanced', 'module', 'm02-erlang-c-and-mmc', 8, 'What does Little''s law need to hold at the base, and so for which of the engine''s two queue models does it hold?', '["Poisson arrivals and exponential service, so it holds for M/M/c only", "A constant service time, so it holds exactly for the M/D/c model only", "Only a steady state, so it holds for M/M/c and M/D/c alike", "One berth and a steady state, so it holds for neither model beyond c = 1"]'::jsonb, 2, 'Little''s law asks nothing about the arrivals or the service beyond a steady state, so it converts a wait to a queue (or back) for either model. It does not compute a wait from nothing: the engine computes the M/M/c wait by eq. 5.3 and the M/D/c wait by an approximation, and the law gives each model''s mean queue from its wait.'),
  ('marine', 'advanced', 'module', 'm02-erlang-c-and-mmc', 9, 'Add two berths to the Ekene quay, four in all, under M/M/c. What mean wait comes back?', '["0.440347 hours, which is the wait the same base returns with three berths", "0.068902 hours, a few minutes, with the berth utilisation down at 0.266667", "0.010236 hours, the wait the same base returns once five berths are stated", "0.025264 hours, the probability of waiting at four berths read as hours"]'::jsonb, 1, 'At 4 berths the berth utilisation is 0.266667 and the engine''s mean wait is 0.068902 hours. 0.440347 and 0.010236 are the three- and five-berth waits; 0.025264 is the four-berth probability of waiting, a share of arrivals. The fourth and fifth berths buy minutes once the third has cut the wait below half an hour.'),
  ('marine', 'advanced', 'module', 'm02-erlang-c-and-mmc', 10, 'Over which vessels is the M/M/c mean wait of 3.180124 hours on the Ekene base averaged?', '["Only the vessels that find both berths taken, the others waiting nothing", "The vessels alongside a berth at the moment a planner looks at the base", "Those that wait longer than one 8.000000-hour service at the quay", "Every arriving vessel, the ones finding a berth free and waiting nothing included"]'::jsonb, 3, 'The mean wait is averaged over all arrivals, the zeros of those that find a free berth included; that is why the vessels that do wait wait longer than 3.180124 hours on average. A plan that quotes the figure says so, with the model, berths, arrivals, working day and service beside it.'),
  ('marine', 'advanced', 'module', 'm02-erlang-c-and-mmc', 11, 'Adan and Resing''s Table 5.1 (Queueing Systems, 26 March 2015) holds the occupation rate at 0.9 with a mean service of 1. Stated as 2 berths, 18 arrivals a day, a 10-hour working day and 1 fixed hour a call, what mean wait does the engine return, against the printed figure?', '["4.263158, which rounds to the 4.26 the table prints for that row", "4.26 exactly, the printed figure, which the engine takes from the table", "9.000000, which is the wait of the table''s one-server row at the same load", "0.852632, which is the engine''s delay probability on that row of the table"]'::jsonb, 0, 'Eighteen arrivals over 10 hours on a 1-hour service run 2 berths at a berth utilisation of 0.900000, and the engine returns 4.263158, which rounds to the printed 4.26. The engine computes the formula and reads no table. 9.000000 is the one-server row; 0.852632 is the delay probability at two servers.'),
  ('marine', 'advanced', 'module', 'm02-erlang-c-and-mmc', 12, 'At five servers in Adan and Resing''s Table 5.1 the engine returns a mean wait of 1.524986, and the table prints 1.53. How does the course read the printed figure?', '["As the engine''s figure rounded half up at two decimals, which is how the table works", "As a sign that the engine''s Erlang C routine drifts at five servers and needs repair", "As a slip in the table, since 1.524986 rounds to 1.52 under any rounding convention", "As a figure that the course adopts, since a printed table outranks a computed value"]'::jsonb, 2, 'The third decimal of 1.524986 is a 4, so half up, half even or half away from zero all give 1.52, and the printed 1.53 sits 0.005014 above the engine''s figure, more than the half unit a two-decimal rounding allows. Every other figure in Tables 5.1 and 5.2 is the engine''s rounded, and the row''s own delay probability of 0.762493 gives 1.524986 by eq. 5.3. The course names the slip and quotes the engine''s figure.'),
  ('marine', 'advanced', 'module', 'm02-erlang-c-and-mmc', 13, 'Adan and Resing''s Table 5.2 holds the surplus capacity at 0.1 of a server. At 20 servers and a berth utilisation of 0.995000, which figures does the engine return for the mean wait and the mean in the system?', '["9.000000 and 9.000000, the one-server row of the same table", "0.275385 and 213.672804, the wait taken from Table 5.1 at 20", "9.74 and 214 exactly, the printed figures read straight back", "9.737327 and 213.672804, which round to the printed 9.74 and 214"]'::jsonb, 3, 'On 199 arrivals a day over 10 hours with a 1-hour service, 20 berths run at 0.995000, and the engine returns a mean wait of 9.737327 and a mean in the system of 213.672804, printed as 9.74 and 214. Holding the spare capacity fixed holds the wait nearly steady while the occupation climbs. 0.275385 is Table 5.1''s wait at 20 servers, where the occupation is 0.9.'),
  ('marine', 'advanced', 'module', 'm02-erlang-c-and-mmc', 14, 'Iversen''s Example 12.3.1 (Teletraffic Engineering Handbook, draft of 20 June 2001) prints mean waits of 0.075 and 0.199, 0.274 in total. What do the engine''s two waits add to?', '["0.273702, which rounds to the printed 0.274 at three decimals", "0.274 exactly, since the engine takes the printed total straight from the example", "0.074697, the first system''s wait alone, since the second is read in hours", "0.199005, the second system''s wait, the first being too small to count"]'::jsonb, 0, 'The engine returns 0.074697 and 0.199005, which add to 0.273702 and round to the printed 0.274; each also rounds to its own printed figure. The golden inputs read the example''s second as the working hour, which changes no figure because every time in the call is in the same unit.'),
  ('marine', 'advanced', 'module', 'm02-erlang-c-and-mmc', 15, 'A planner types servers where the shore base call expects its berth count. What does the engine return?', '["A result that reads servers as the berth count, since Adan and Resing and Iversen both write their formulas with servers, and a note", "servers is not an accepted key; the accepted keys at the top level are berths, arrivalsPerDay, workingHoursPerDay, service, model, targetMeanWaitHours", "servers is not an accepted key; the accepted keys at the top level are arrivalsPerDay, workingHoursPerDay, service, model, targetMeanWaitHours", "A result on one berth with the servers key dropped, followed by the saturation refusal once the load is found to be above one"]'::jsonb, 1, 'The engine checks its accepted keys before it reads an input, so an unknown key is refused first, by name, with the full list, in its own words as the key shows. It maps no synonym to an input and drops no key silently. The accepted keys it lists include berths, the key the planner meant.'),
  ('marine', 'advanced', 'module', 'm03-constant-service-and-mdc', 1, 'Run under M/D/c, how long does a vessel wait on average at the two-berth Ekene quay, with its 3.2 daily arrivals over 24 working hours and 8-hour concurrent calls?', '["3.180124 hours, the wait the same base returns when its model is M/M/c", "0.440347 hours, the M/M/c wait once a third berth is stated", "0.259397 hours, the M/D/c wait once a third berth has been stated", "1.665786 hours, the Cosmetatos approximation for a constant service"]'::jsonb, 3, 'As M/D/c the engine applies the Cosmetatos (1975) approximation as Liu, Pantelidis, Tam and Chow print it (arXiv 2102.05851v2, eq. (2), CC BY 4.0) and returns 1.665786 hours. 3.180124 is the M/M/c wait; 0.440347 is the three-berth M/M/c wait; 0.259397 is the three-berth M/D/c wait the target search reports.'),
  ('marine', 'advanced', 'module', 'm03-constant-service-and-mdc', 2, 'On the Ekene base run as M/D/c, what does the engine return for the probability of waiting?', '["0.371014, carried over unchanged from the M/M/c run of the same base", "No figure: the engine gives no delay probability for M/D/c and its basis says so", "0.106417, the figure the three-berth M/M/c run returns for the base", "The M/M/c probability halved, as the wait it scales is halved for a constant service"]'::jsonb, 1, 'The engine''s basis for M/D/c ends "probabilityWait is not given for M/D/c", and the calculator''s tile reads "not given for M/D/c". 0.371014 belongs to M/M/c alone; 0.106417 is the three-berth M/M/c figure; vessels that find a free berth wait nothing under either model, and no probability is halved along with the wait.'),
  ('marine', 'advanced', 'module', 'm03-constant-service-and-mdc', 3, 'Switching the Ekene base from M/M/c to M/D/c with every input held, which figure stays at the same value in the engine''s return?', '["The mean wait, 3.180124 hours, as the arrivals are unchanged", "The mean time at the base, 11.180124 hours", "The berth utilisation, 0.533333, set by the service only through its mean", "The probability of waiting, 0.371014, since both models share Erlang''s C formula"]'::jsonb, 2, 'The berth utilisation is the arrivals an hour times the mean service over the berths, so it depends on the service only through its mean; how the service times spread does not enter, and it is 0.533333 under both models. What the model changes is the wait (1.665786 hours as M/D/c, the Cosmetatos approximation, against 3.180124 as M/M/c), and so the time at the base; M/D/c returns no probability of waiting.'),
  ('marine', 'advanced', 'module', 'm03-constant-service-and-mdc', 4, 'As Liu et al. print it in eq. (2), how is the M/D/c mean wait built from the M/M/c wait at the same berths and load?', '["Halved, then raised by a correction in (1 - rho)(c - 1)(sqrt(4 + 5c) - 2) / (16 rho c)", "Doubled, then reduced by a correction that grows as the berths get busier toward saturation", "Taken as it stands, since the two models share a delay probability and so share a wait", "Halved at every berth count, which is exact for any number of berths at any berth utilisation"]'::jsonb, 0, 'Wq(M/D/c) = Wq(M/M/c) / 2 x (1 + (1 - rho)(c - 1)(sqrt(4 + 5c) - 2) / (16 rho c)). The correction grows with the idle share and the berths beyond the first and shrinks as rho rises, since rho is in its denominator. The halving alone is exact only at one berth.'),
  ('marine', 'advanced', 'module', 'm03-constant-service-and-mdc', 5, 'Why does the Cosmetatos correction vanish at one berth?', '["At one berth the berth utilisation must equal 1, so the factor (1 - rho) is zero and drops the term", "With one berth the term 16 rho c in the denominator grows without limit and the fraction goes to zero", "The factor (c - 1) is zero at c = 1, leaving half the M/M/1 wait, the exact Pollaczek-Khinchin figure", "The engine skips the correction at one berth by a stated rule, since the approximation is untested there"]'::jsonb, 2, 'Put c = 1 into eq. (2) and (c - 1) is zero, so the wait is half the M/M/1 wait, which is the Pollaczek-Khinchin mean value formula for M/D/1 (Adan and Resing, s. 7.6, eqs 7.14 to 7.16). A berth utilisation of 1 is refused, the denominator stays finite, and no rule skips anything: the arithmetic does it.'),
  ('marine', 'advanced', 'module', 'm03-constant-service-and-mdc', 6, 'One berth, a constant service of 1 hour and a berth utilisation of 0.900000. What M/D/c mean wait does the engine return, and how does it compare with M/M/c at the same load?', '["9.000000 hours, the same as M/M/c, since one berth leaves no room for the service spread to act", "4.263158 hours, the wait Adan and Resing''s Table 5.1 prints for the same load at two servers", "0.900000 hours, the berth utilisation times the service, the time a call is under way on average", "4.500000 hours, half the 9.000000 hours M/M/c returns, as the Pollaczek-Khinchin formula gives"]'::jsonb, 3, 'The Pollaczek-Khinchin formula for M/D/1 gives rho S / (2 (1 - rho)): 0.9 times 1 over 2 times 0.1, which is 4.500000 hours, and the engine returns 4.500000. M/M/1 at the same load waits 9.000000, the first row of Table 5.1. With exponential service the spread of service times doubles the wait; 4.263158 is the two-server row.'),
  ('marine', 'advanced', 'module', 'm03-constant-service-and-mdc', 7, 'A stated case puts 3 berths at a berth utilisation of 0.800000 with 1-hour calls. Comparing the two queue models on it, which pair of waits comes back?', '["0.552578 hours as M/D/c (the Cosmetatos approximation), 1.078652 as M/M/c", "0.259397 hours as M/D/c, the Ekene three-berth figure, against 1.078652 as M/M/c", "1.078652 hours under both models, since the two models agree above one berth", "0.552578 hours under both models, the service time being fixed at 1"]'::jsonb, 0, 'The engine returns 0.552578 hours as M/D/c and 1.078652 as M/M/c on the same inputs: a little over half, because the correction of eq. (2) adds to the halved wait at three berths. 0.259397 belongs to the Ekene base at three berths, a different load. The two models part at every berth count, and the M/M/c call knows nothing of the service being constant.'),
  ('marine', 'advanced', 'module', 'm03-constant-service-and-mdc', 8, 'On the Ekene base the engine returns 1.665786 hours as M/D/c (the Cosmetatos approximation) and 3.180124 as M/M/c. What ratio of the two does the course derive, and what does it show?', '["0.500000: an exact half, the correction vanishing at two berths", "0.523812: a half, plus the Cosmetatos correction of eq. (2)", "0.371014: the probability of waiting, which scales the M/D/c wait down", "0.533333: the berth utilisation of the base, which the ratio copies"]'::jsonb, 1, '1.665786 over 3.180124 is 0.523812: the halving plus a correction, since the Ekene base has 2 berths and the (c - 1) factor is 1. The correction vanishes only at one berth. The ratio is set by c and rho through eq. (2); it is no copy of the berth utilisation.'),
  ('marine', 'advanced', 'module', 'm03-constant-service-and-mdc', 9, 'Where does the course take the M/D/c formula from, and how does the engine label its figures?', '["From Cosmetatos''s 1975 paper, read in full by the course, with every figure labelled exact", "From Adan and Resing''s Table 5.1, where the M/D/c rows sit beside the M/M/c rows, labelled exact", "From Iversen''s handbook, s. 12.2, whose Erlang''s C formula covers constant service, labelled exact", "From Liu, Pantelidis, Tam and Chow (arXiv 2102.05851v2, CC BY 4.0) eq. (2), labelled an approximation"]'::jsonb, 3, 'Cosmetatos (1975) was not read directly: the formula is taken as Liu et al. print it in eq. (2) of arXiv 2102.05851v2 (11 February 2021, CC BY 4.0), which also states that M/D/c has no closed form for its mean wait. The engine labels every M/D/c figure an approximation. Table 5.1 and Erlang''s C formula are M/M/c.'),
  ('marine', 'advanced', 'module', 'm03-constant-service-and-mdc', 10, 'Holding the two-berth Ekene quay to a 1-hour mean wait under M/M/c: what reason does the berth search give?', '["2 berths, the base as stated, since its 3.180124-hour wait is inside a working day", "4 berths, the first count whose wait of 0.068902 hours falls to a few minutes", "3 berths are the fewest with a mean wait at or below 1 hour (0.440347 hours)", "No berth count, since the 3.180124-hour wait at 2 berths misses the target"]'::jsonb, 2, 'The engine searches from the fewest berths that keep the berth utilisation below 1 upward, under the stated model, and returns the first whose mean wait is at or below the target, with its reason in its own words as the key shows. Two berths wait 3.180124 hours, above 1; three wait 0.440347; four are more than the fewest.'),
  ('marine', 'advanced', 'module', 'm03-constant-service-and-mdc', 11, 'Under M/D/c, which berth count and wait does the search report for the Ekene base''s 1-hour target?', '["2 berths, since the M/D/c wait at 2 berths is short enough to meet the 1-hour target", "3 berths, where the constant-service wait falls to 0.259397 hours, inside the target", "3 berths with a wait of 0.440347 hours, the same figure the M/M/c search returns", "No berth count, since M/D/c gives no delay probability for the search to work from"]'::jsonb, 1, 'The search uses the stated model: as M/D/c two berths wait 1.665786 hours, above the target, and three wait 0.259397 (the Cosmetatos approximation), so the engine returns 3 berths with that reason. 0.440347 is the three-berth wait as M/M/c. The M/D/c search needs only the wait, which the approximation gives.'),
  ('marine', 'advanced', 'module', 'm03-constant-service-and-mdc', 12, 'How does the engine''s berth-target search choose where to start and where to stop?', '["From the whole part of the offered load plus one, upward to 100 berths, under the stated model", "From one berth upward to the berths stated in the call, under M/M/c whatever the stated model is", "From 100 berths downward, until the wait first rises above the target, under the stated model", "From the stated berths upward, one at a time, until the berth utilisation first falls below 0.5"]'::jsonb, 0, 'The search starts at the fewest berths that keep the berth utilisation below 1, the whole part of the offered load plus one, so it never offers a count with no steady state, and it runs to the cap of 100 under the model the call states. It returns the first count whose wait meets the target.'),
  ('marine', 'advanced', 'module', 'm03-constant-service-and-mdc', 13, 'A call states a base whose M/M/c wait at one berth prints as 9.000000 hours, with a target mean wait of 9 hours. What does the engine return, and what reading does that rest on?', '["2 berths, since a wait that merely equals the target has not been brought under it, which the engine requires", "No berth count, because a target equal to the wait is read as unreachable and is reported with a reason", "A refusal on targetMeanWaitHours, since a target must lie strictly below the wait at the berths stated", "1 berth, because the engine reads a target as met at or below it; met only strictly below would give a second berth"]'::jsonb, 3, 'The engine''s reason, verbatim: "1 berth is the fewest with a mean wait at or below 9 hours (9 hours)". At or below is the engine''s stated reading; the alternative it names, met only strictly below, would push the answer to a second berth. The course teaches it as the engine''s reading, and no graded figure rests on it.'),
  ('marine', 'advanced', 'module', 'm03-constant-service-and-mdc', 14, 'Zero hours of waiting is set as the berth target. How does the engine answer?', '["A refusal on targetMeanWaitHours, since a target of 0 is outside the accepted range", "A result with a reason: no berth count up to 100 gives a mean wait at or below 0 hours", "100 berths, the cap of the search, with the smallest wait it could reach up there", "The berths as stated, since a target of 0 is read as asking for no target at all"]'::jsonb, 1, 'Every steady-state queue has some wait, so 0 hours is never met; the engine returns its figures with the reason "no berth count up to 100 gives a mean wait at or below 0 hours" and no berth count. A target of 0 is accepted; the refusal belongs to a negative target, "targetMeanWaitHours must be a finite number at or above 0; got -1".'),
  ('marine', 'advanced', 'module', 'm03-constant-service-and-mdc', 15, 'Why does a constant service time give a shorter mean wait than an exponential one at the same arrivals and mean service?', '["The berth utilisation is lower under constant service, so the berths are idle more often", "Constant service lets the base serve two vessels at one berth whenever the calls are short", "No call runs long, so the vessel ahead is less likely to hold a berth far past the mean", "Under constant service the arrivals are spaced evenly, so vessels never bunch at the base"]'::jsonb, 2, 'With exponential service some calls run far past the mean, and a vessel that arrives during one waits for it; with a constant service none does. The berth utilisation is the same under both models, the berths still serve one vessel each, and the arrivals are Poisson in both, bunching alike.'),
  ('marine', 'advanced', 'module', 'm04-weather-and-demand-variability', 1, 'Where does the engine''s fleetVariability function get its random numbers and its summaries?', '["From the canonical lib/stats: one mulberry32 stream on the stated seed, triInvCDF and basicStats", "From a sampler of its own inside the marine engine, written for the weather and the demand", "From the clock of the machine it runs on, so every run gives a fresh and independent answer", "From a table of past Ekene weeks, resampled with replacement to build the spread of weeks"]'::jsonb, 0, 'The engine carries no sampler and no percentile code of its own: it imports mulberry32, triInvCDF and basicStats from lib/stats/stats.js and the exceedance sentence from lib/conventions/percentile.js. It reads no clock and fits nothing to past weeks; the seed is a stated input.'),
  ('marine', 'advanced', 'module', 'm04-weather-and-demand-variability', 2, 'In each draw of the engine''s Monte Carlo, in what order are the two factors taken from the stream?', '["The demand factor first, since demand sets the voyages before the weather acts", "Both from one uniform number, so the two factors always move together", "The weather factor first, then the demand factor, each only when it varies", "Whichever varies more is drawn first, as judged from its min and its max"]'::jsonb, 2, 'The engine''s basis states it: per iteration the weather factor is drawn first, then the demand factor, each only when it varies. If the weather is a plain number it takes no uniform number and the demand factor takes the first. Each factor has its own uniform draw, so the two are drawn independently; the order is fixed, which is what lets the same seed give back every draw.'),
  ('marine', 'advanced', 'module', 'm04-weather-and-demand-variability', 3, 'A triangular factor is stated with its max equal to its min. What does the engine''s Monte Carlo do with it?', '["Refuses it, since a triangular must have its min strictly below its mode and its max", "Draws nothing for it, since a triangular only varies when its max is above its min", "Draws a uniform number for it anyway, and every draw then returns the same value", "Replaces it with the mode of the other factor, so that at least one of the two still varies"]'::jsonb, 1, 'A factor varies when it is a triangular { min, mode, max } with max above min; a plain number, or a triangular whose max equals its min, is fixed and takes no uniform number from the stream. The engine''s order rule is min <= mode <= max, so an equal triangle is accepted, and nothing is borrowed from the other factor.'),
  ('marine', 'advanced', 'module', 'm04-weather-and-demand-variability', 4, 'What does the demand factor of a draw multiply, in the engine''s Monte Carlo?', '["The minimum visits of every installation, rounded up to whole visits after each draw is made", "Voyages after rounding, so that each draw scales the voyage count of the plan directly", "The vessel-days of the plan at the modes, as a single multiplier on the whole of the fleet''s work", "Every installation''s demand in the period: deck area, deck weight and every bulk product"]'::jsonb, 3, 'The demand factor multiplies every installation''s demand, deck area, deck weight and each bulk product alike, and each draw then sizes the fleet exactly as fleetSize does. The minimum visits are a stated count and do not scale; the voyages and the vessel-days follow from the scaled demand through the stated rounding.'),
  ('marine', 'advanced', 'module', 'm04-weather-and-demand-variability', 5, 'On the Ekene week (the PSV milk run, weather triangular 1, 1.2, 1.6 on sailing and field time, demand triangular 0.85, 1, 1.3, 2 planned vessels, seed 20260927, 20000 draws), what does the engine return as the plan at the modes?', '["10.239206 vessel-days and 2.001400 vessels, the mean of the sampled weeks on seed 20260927", "10.345455 vessel-days and 2 vessels, the figures fleetSize returns for the same week, no draw", "10.412277 vessel-days, the P50 of the draws, which is the plan once the draws are sorted", "7.977705 vessel-days, the P90 of the draws, the week the plan must be sized to cover"]'::jsonb, 1, 'The plan at the modes takes the weather factor at 1.2 and the demand factor at 1, and it is the fleetSize week: 10.345455 vessel-days and 2 vessels. It is no draw, so it does not move with the seed. 10.239206 and 2.001400 are the sampled means, 10.412277 the P50 and 7.977705 the P90, each an estimate on seed 20260927 and 20000 draws.'),
  ('marine', 'advanced', 'module', 'm04-weather-and-demand-variability', 6, 'The seed is left out of a fleetVariability call. What comes back?', '["seed must be a whole number from 0 to 4294967295 (there is no default, so every run can be reproduced); got nothing", "A result drawn on seed 0, the first value in the accepted range, with that seed printed beside every figure", "A result drawn on a seed taken from the clock, with the seed it chose printed in the basis so it can be repeated", "seed must be a whole number from 0 to 4294967295 (there is no default, so every run can be reproduced); got -1"]'::jsonb, 0, 'The seed has no default, so a call without one is refused in the engine''s own words, ending "got nothing". The message ending "got -1" is the refusal of a negative seed. The engine reads no clock and picks no seed for the planner, because a run nobody can repeat cannot be checked.'),
  ('marine', 'advanced', 'module', 'm04-weather-and-demand-variability', 7, 'On the Ekene week with seed 20260927 and 20000 draws, the engine returns a P90 and a P10 of the vessel-days. Which is which, as the engine reports them?', '["P90 11.908677, the figure that 90 percent of the sampled weeks stay at or below; P10 7.977705", "P90 10.412277 and P10 10.239206, the median and the mean of the sampled vessel-days", "P90 16.024716 and P10 6.757591, the largest and the smallest of the sampled weeks", "P90 7.977705, the low figure met or exceeded in 90 percent of the draws; P10 11.908677"]'::jsonb, 3, 'For a requirement the engine takes the P90 as the LOW figure, the 10th percentile of the sorted draws at index floor(0.1 n), and the P10 as the high figure, the 90th percentile: 7.977705 and 11.908677, both estimates on seed 20260927 and 20000 draws. This is the engine''s stated reading, with its sentence from lib/conventions/percentile.js; P90 read at the high side is the alternative it names. 10.412277 is the P50, 10.239206 the mean, and 16.024716 and 6.757591 the max and min.'),
  ('marine', 'advanced', 'module', 'm04-weather-and-demand-variability', 8, 'Which sentence does the engine return beside its percentiles to fix what its P90 means?', '["P90 means the value that 90% of the draws stay at or below, the upper tail of the requirement.", "P90 means the 90th percentile of the sorted draws, at index floor(0.9 n), per lib/stats.", "P90 means a 90% probability the actual quantity meets or exceeds this value, per SPE PRMS.", "P90 means the requirement a planner should size the fleet to, in nine weeks out of ten."]'::jsonb, 2, 'The engine returns the exceedance sentence of lib/conventions/percentile.js verbatim, as the key shows. Under it the P90 of a requirement is the figure met or exceeded in 90 percent of the draws, the low one. The other three read the P90 at the high side or as a sizing rule, which the engine does not state.'),
  ('marine', 'advanced', 'module', 'm04-weather-and-demand-variability', 9, 'The Ekene week states 2 planned vessels at 6.5 available days a vessel. When does the engine count a draw as short?', '["When its vessel-days are strictly above 13.000000, the planned vessels times the available days", "When its vessel-days reach 13.000000 or more, a need equal to the capacity in vessel-days included", "When its vessel-days pass the 10.345455 of the plan at the modes, the fleet''s planned workload", "When its whole vessels required come to 2 or more, the count of planned vessels on the week"]'::jsonb, 0, 'The planned capacity in vessel-days is the planned vessels times the available days, 2 times 6.5, which is 13.000000, and a draw is short when its vessel-days are strictly above it at twelve significant digits. That strict comparison is the engine''s stated reading; short at equality is the alternative it names. The plan at the modes is no capacity.'),
  ('marine', 'advanced', 'module', 'm04-weather-and-demand-variability', 10, 'On the Ekene week with 2 planned vessels, seed 20260927 and 20000 draws, what share of the draws does the engine return as short, and what expected shortfall?', '["0.998600 of the draws short, the share that needs exactly 2 whole vessels in the week", "0.001400 of the draws short, with 0.000686 expected short vessel-days, both estimates", "0.085000 of the draws short, with 0.025759 expected short vessel-days over the draws", "0.001700 of the draws short, the share the same inputs give on seed 7 and 20000 draws"]'::jsonb, 1, 'On seed 20260927 and 20000 draws the engine returns a probability short of 0.001400 and an expected shortfall of 0.000686 vessel-days, averaged over every draw with the covered draws at zero. 0.998600 is the share needing 2 vessels; 0.085000 and 0.025759 are the AHTS on dedicated voyages (seed 11, 5000 draws); 0.001700 is seed 7. Each is an estimate on its own seed and draws.'),
  ('marine', 'advanced', 'module', 'm04-weather-and-demand-variability', 11, 'Both factors are held fixed, so every draw needs 14.000000 vessel-days, and 2 planned vessels give exactly 14.000000 (seed 4, 20 draws). What probability short does the engine return?', '["1.000000, since every one of the 20 draws reaches the planned capacity in vessel-days", "0.500000, half the draws being read as short when a need sits right at the capacity", "No figure, since a Monte Carlo with both factors fixed is refused by the engine outright", "0.000000, since a need equal to the planned capacity in vessel-days is covered"]'::jsonb, 3, 'Short means strictly above the planned capacity, so a need exactly at it is not short: the engine returns 0.000000. That is its stated reading; the alternative, short at equality, would count every draw here. With one vessel fewer every draw is short, by 7.000000. Fixed factors are accepted, and every draw is then the fleetSize week.'),
  ('marine', 'advanced', 'module', 'm04-weather-and-demand-variability', 12, 'The Ekene inputs are run on seed 7 with 20000 draws, beside the run on seed 20260927. Which figure is the same in both runs?', '["The mean vessel-days, since 20000 draws settle it to the sixth decimal", "The P90 of the vessel-days, since the percentile rule does not change", "The plan at the modes, 10.345455 vessel-days, since it is no draw", "The probability short, since the planned vessels have not changed"]'::jsonb, 2, 'On seed 7 the mean is 10.249964, the P90 8.023594, the P10 11.928203 and the probability short 0.001700, against 10.239206, 7.977705, 11.908677 and 0.001400 on seed 20260927. The plan at the modes stays at 10.345455 because it is computed at the modes with no sampling. That is why every sampled figure is quoted with its seed and draws.'),
  ('marine', 'advanced', 'module', 'm04-weather-and-demand-variability', 13, 'A fleetVariability call states a demand factor with min 1, mode 0.9 and max 1.3. What does the engine return?', '["demandFactor must have min <= mode <= max; got min 1, mode 0.9, max 1.3", "A result with the min and the mode swapped into order, and a note of the swap", "A result that reads the triangular as fixed at its mode of 0.9 for every draw", "demandFactor must be a number at or above 0 or a triangular distribution"]'::jsonb, 0, 'A triangular must keep min at or below mode at or below max, and the engine refuses one that does not, in its own words as the key shows. It reorders nothing and fixes nothing. The other message is the start of the refusal of a demand factor that is neither a number nor a whole triangular.'),
  ('marine', 'advanced', 'module', 'm04-weather-and-demand-variability', 14, 'A weather factor inside a fleetVariability call is stated as a triangular with a min of 0.9. What does the engine return?', '["A result, the calm floor of 1 binding plain numbers only", "A result with the min raised to 1 and a note of it", "weather.factor must be a finite number from 1 to 10; got 0.9", "weather.factor.min must be at or above 1; got 0.9"]'::jsonb, 3, 'The weather factor keeps its calm floor of 1 and its cap of 10 inside a triangular as well as outside it, and the engine refuses the min by its own path, in its own words as the key shows. It moves no input. The "from 1 to 10" message is the refusal of a plain weather factor.'),
  ('marine', 'advanced', 'module', 'm04-weather-and-demand-variability', 15, 'Why is no graded answer in this course a Monte Carlo figure, although the variability calculator prints many?', '["Sampled figures are too rough to grade, since 20000 draws never settle to the sixth decimal", "A graded answer needs one right value on any machine, and a sampled figure moves with its seed", "The capstone runs its Monte Carlo on a hidden seed, so a learner cannot reproduce the figure", "A sampled figure is the uncertainty course''s to grade, so this course only shows the method"]'::jsonb, 1, 'Every graded figure is a return value of the engine on fixed inputs. A sampled figure is a function of its seed and draws, so it is taught as an estimate with both, and no mark rests on it; a plan still reports it, because a fleet manager needs the spread. No seed is hidden: the seed is always a stated input.'),
  ('marine', 'advanced', 'module', 'm05-readings-and-boundaries', 1, 'To how many significant digits must two figures agree for the engine to treat them as a tie, and where does it apply that rule?', '["6, the decimals it prints every figure to, for each comparison it makes in a message", "16, the digits of a binary double, so that two figures tie only when they are equal", "12, its DEFAULTS.TIE_DIGITS: for a tie, a capacity check and a count rounded up", "2, the decimals of Adan and Resing''s printed waits, for the published checks alone"]'::jsonb, 2, 'The engine states one rule for every comparison where binary doubles would mislead: two figures tie when they agree to 12 significant digits (DEFAULTS.TIE_DIGITS). A capacity check passes when the 12-digit load is at or below the 12-digit capacity; a count rounded up is the ceiling of the 12-digit figure; a binding tie goes to the first constraint in the stated order. Six decimals is only how figures print.'),
  ('marine', 'advanced', 'module', 'm05-readings-and-boundaries', 2, 'A week''s only demand is 2.1 m2 of deck area, with no minimum visits, against a voyage capacity of 0.7 m2 of deck area; the division in binary doubles lands one step above 3. With voyages rounded up, what voyage count does the engine return?', '["3 voyages, since the count rounds up on its twelve-digit figure, which is 3", "4 voyages, the ceiling of the raw double read straight from the binary arithmetic", "A fractional count just above 3, since a count rounded up keeps its binary tail", "A refusal, since a demand ratio must come out a whole number to be rounded"]'::jsonb, 0, 'The engine rounds a count up on its twelve-digit figure, which is exactly 3, and returns 3 voyages. That is the engine''s stated reading; the alternative it names, the ceiling of the raw double, would give 4 for what is three voyages of demand. No graded figure moves under either.'),
  ('marine', 'advanced', 'module', 'm05-readings-and-boundaries', 3, 'A week''s only demand, 300.001 m2 of deck area with no minimum visits, meets a voyage capacity of 100 m2 of deck area, with voyages rounded up. What does the engine return, and why does the twelve-digit rule not hold it at 3?', '["3 voyages, since the twelve-digit rule reads anything within a thousandth as a tie", "4 voyages, since a thousandth of a square metre over 3 is plain at twelve digits", "3 voyages and a remainder, since a count keeps the small excess that it carries", "A refusal, since a demand that is not a whole multiple of a capacity is not accepted"]'::jsonb, 1, 'The ratio sits a hundred-thousandth above 3, a difference in the sixth significant digit, so its twelve-digit ceiling is 4 and the engine returns 4 voyages. The rule absorbs the binary noise of a double, a step far beyond the twelfth digit, and blurs no real difference.'),
  ('marine', 'advanced', 'module', 'm05-readings-and-boundaries', 4, 'Two deck cargoes of 0.1 and 0.2 m2 go on a deck whose area capacity is 0.3 m2. In binary doubles their sum, and so the deck area utilisation, lands a hair above the capacity. What does the engine return?', '["Overloaded on deck area, since the utilisation in the double lies a hair above 1", "A refusal on the deck cargo, since decimal areas cannot be summed exactly by the engine", "Feasible, since the engine rounds every utilisation to six decimals before it checks it", "Feasible, with deck area binding at 1.000000, read at capacity by the twelve-digit rule"]'::jsonb, 3, 'The double sum sits a hair above 0.3, so the utilisation sits a hair above 1; the twelve-digit rule reads the load as at the capacity, and a load exactly at a capacity is feasible, the engine''s first stated reading. The engine checks at twelve significant digits; six decimals is only how the figure prints.'),
  ('marine', 'advanced', 'module', 'm05-readings-and-boundaries', 5, 'The engine refuses a base with 2 berths at 30 arrivals a day, whose exact bound is a repeating decimal printed as 26.666667. Which most-arrivals figure does its message print, and why?', '["26.666666, rounded down at the sixth decimal so that the printed figure is accepted", "26.666667, the exact bound at six decimals, rounded half up in the usual way", "26, the whole part of the bound, since arrivals a day are counted whole", "30, the arrivals as typed, with the berth utilisation of 1.125 beside them"]'::jsonb, 0, 'Ordinary rounding gives 26.666667, which is above the exact bound and would itself be refused. The engine prints the six-decimal figure nearest the bound on the accepted side, 26.666666, and adds "(rounded down at the sixth decimal so that it is accepted)" because it differs from the exact bound. Typing it back in passes.'),
  ('marine', 'advanced', 'module', 'm05-readings-and-boundaries', 6, 'A base with 2 berths is stated at exactly 20 arrivals a day, which puts its berth utilisation at 1. Which most-arrivals figure does the engine''s refusal print?', '["20, the exact bound, which the engine accepts as the edge", "19, the largest whole number of arrivals below the bound", "20.000000, the exact bound written out to six decimals", "19.999999, since the exact bound of 20 is itself refused"]'::jsonb, 3, 'A steady state needs a berth utilisation strictly below 1, so 20 arrivals a day is refused. The engine prints 19.999999, the nearest six-decimal figure its rule accepts, with the note that it was rounded down. Arrivals a day need not be whole.'),
  ('marine', 'advanced', 'module', 'm05-readings-and-boundaries', 7, 'Two units on a deck plan share the same footprint area. Under first-fit decreasing, which does the engine place first, and on what footing?', '["The lighter one, so that the deck load fills more slowly on the early voyages of the plan", "The one booked first, since first-fit decreasing keeps the booking order among equal areas", "The heavier one, then by item id and unit number, on the engine''s stated tie reading", "Whichever has the longer side, since a longer unit is harder to place once the deck fills up"]'::jsonb, 2, 'The engine sorts by footprint area and breaks a tie by the heavier unit first, then the item id, then the unit number; its basis says so. That is the engine''s stated reading, and the alternative it names puts the lighter first. First fit in the booked order is a different rule, and the engine checks no deck shape, so a unit''s length never enters the order.'),
  ('marine', 'advanced', 'module', 'm05-readings-and-boundaries', 8, 'Which of these is a choice a call must state, and so the engine''s input, as distinct from a reading the engine itself states?', '["That a berth target is met at or below the target wait, the engine''s own", "The queue model, M/M/c or M/D/c, a required input a plan names", "Short counted only strictly above the planned capacity in vessel-days", "The P90 of a requirement taken as its low figure, met in 90 percent of draws"]'::jsonb, 1, 'The activities the weather slows, the voyage and vessel rounding rules, the packing rule, the queue model and the concurrent choice are inputs, each required, and a capstone states each one it uses. The inclusive berth target, short strictly above and the low P90 are readings the engine states where no source fixes a convention.'),
  ('marine', 'advanced', 'module', 'm05-readings-and-boundaries', 9, 'Which pair of the engine''s boundaries shows that no single boundary rule runs through the whole engine?', '["A load at a capacity is feasible, while a berth utilisation of exactly 1 is refused", "A load at a capacity is feasible, and a wait equal to a target meets the target", "A need at the planned capacity in vessel-days is covered, as is an exact deck fill", "A weather factor of 1 is accepted, as is a usable fraction of exactly 1 on a deck"]'::jsonb, 0, 'Each rule draws its own edge. A capacity is inclusive (a load at it is feasible) while the steady state is strict (a berth utilisation of 1 has no steady state and is refused). The other three pairs each join two inclusive edges, so they show no difference between rules.'),
  ('marine', 'advanced', 'module', 'm05-readings-and-boundaries', 10, 'On the voyage and fleet calculators, which weather factors does the engine accept and which does it refuse?', '["0.9 is accepted as a fair-weather factor; 10.5 is refused as above the cap of 10 set at the top of the range", "Every factor above 0 is accepted, since the weather factor is a stated input with no bounds", "1 is accepted as the calm factor; 0.9 and 10.5 are refused, below the floor and above the cap", "1 is refused as a factor that changes nothing; 0.9 and 10.5 are both accepted with a warning"]'::jsonb, 2, 'The weather factor must be a finite number from 1 to 10: 1 is the calm factor and accepted, and the engine refuses 0.9 and 10.5, each with "weather.factor must be a finite number from 1 to 10" and the figure it got. The same floor and cap hold inside a triangular in the Monte Carlo.'),
  ('marine', 'advanced', 'module', 'm05-readings-and-boundaries', 11, 'Skoko et al. (J. Mar. Sci. Eng. 12(2), 263, 1 February 2024, CC BY 4.0) print the PSV''s optimal fuel cost as USD 186,274.10. What do their rounded Table 5 days give through the engine, and what does the course do?', '["USD 186,274.10 exactly, the printed total, which the engine rebuilds from the days", "80847.360000, the PSV total once the days are read as field time at the sailing burn", "186214.104000, which the course treats as a slip and corrects in the printed total", "186214.104000, 59.996000 short, so the course leaves the PSV total out and uses the AHTS row"]'::jsonb, 3, 'The rounded days of Table 5 give 186214.104000 through the engine, 59.996000 short of the printed USD 186,274.10, so the table''s rounded days cannot rebuild its total. The course uses the AHTS row, whose USD 80,847.36 the engine reproduces as 80847.360000, and leaves the PSV total out; it corrects no one''s table.'),
  ('marine', 'advanced', 'module', 'm05-readings-and-boundaries', 12, 'Iversen''s Example 12.3.1 is set in seconds. How do the golden inputs handle that, and does it move any figure?', '["They convert each second to a fraction of an hour, which moves every wait by one factor", "They read the second as the working hour, which moves no figure since every time is in one unit", "They read the second as a working day, which leaves the waits in days to be converted", "They drop the units altogether, and the engine refuses any time stated without one"]'::jsonb, 1, 'Iversen''s handbook was read in its ITU-D draft of 20 June 2001. The golden inputs read its second as the working hour; because the service, the arrivals and the waits are all in that one unit, no figure moves, and both waits reproduce the printed 0.075 and 0.199 at three decimals.'),
  ('marine', 'advanced', 'module', 'm05-readings-and-boundaries', 13, 'Why does the course cite the Wikipedia article on first-fit decreasing as revision 1317275412 of 17 October 2025?', '["Because that revision fixed an error in the capacity 60 and 61 example the engine needed", "Because the licence of the article, CC BY-SA 4.0, applies only to one named revision", "Because Johnson''s 1973 thesis is quoted in that revision and in no other", "Because the page changes over time, the course cites the revision whose examples it ran"]'::jsonb, 3, 'A living page moves, so the course names the revision it read and takes the examples as that revision prints them, citing it without pasting its wording. The licence covers every revision, no revision is described as a repair, and Johnson''s 1973 thesis and Dosa''s 2007 paper were not read directly.'),
  ('marine', 'advanced', 'module', 'm05-readings-and-boundaries', 14, 'Skoko et al. treat 85% of a vessel''s carrying capacity as usable, and the Ekene fixture states a usable deck fraction of 0.75. Which does the engine hold?', '["Neither: the usable fraction is a required input on every call, with no figure held", "The 85% of Skoko et al., since a published figure is applied wherever the call is silent", "The 0.75 of the Ekene fixture, since the synthetic cluster sets the engine''s usual fraction", "Both, applying 0.75 to the deck area and 85% to the deadweight of every vessel"]'::jsonb, 0, 'The engine holds no domain figure: the usable fraction is required on every call, and a call without it is refused by name. A usable fraction of 1 is accepted, and 0 and 1.1 are refused. The two figures come from two places, and each call states its own.'),
  ('marine', 'advanced', 'module', 'm05-readings-and-boundaries', 15, 'On a fleet case whose vessels before rounding come to 1.500000, with the vessel rounding stated as nearest, what does the engine return?', '["1 vessel, since a half rounds down to keep the fleet as small as the rounding rule allows", "1.500000 vessels, since the nearest rule leaves a figure that is exactly at a half as it is", "2 vessels, on the engine''s stated reading that the nearest whole vessel rounds a half up", "2 vessels, because every rounding rule the engine offers takes a fleet count up in the end"]'::jsonb, 2, 'Under the nearest rule the engine rounds a half up and returns 2 vessels. That is its stated reading; the alternative, halves rounded down, would give 1 vessel and a short week. The same rule rounds 1.416667 down to 1 and reports the shortfall; only the up rule always rounds up.'),
  ('marine', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 1, 'A planner wants the voyage plan to allow for waiting on weather and a sea state above a limit. What does the engine take in their place?', '["A wave-height series it reads from a forecast and turns into windows", "One stated weather factor applied to the activities the call names", "Weather windows it computes from the season and the vessel type", "A standard allowance it holds for each month of the rainy season"]'::jsonb, 1, 'The engine computes no weather windows, wave heights or waiting on weather: it takes one stated factor on the stated activities, and fuel follows the time. It reads no forecast and holds no seasonal figure; the factor and the activities it slows are required inputs.'),
  ('marine', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 2, 'A plan needs the hire rate of the PSV and the port fees at the supply base. Where does the engine leave those, and which course owns them?', '["Inside the fleet call, which multiplies the vessel-days by a stated day rate for each vessel", "Inside the shore base call, which prices each berth-hour of service at a stated port tariff", "Outside the engine, and the materials course prices them along with the spares on the deck", "Outside the engine, which prices fuel alone; hire and contracts belong to the procurement course"]'::jsonb, 3, 'The engine takes a stated fuel price and nothing else in money: vessel hire, port fees and a contract for the vessel are the subject of Procurement, Tendering & Contracting. The fleet and base calls price nothing, and the materials course owns stock and spares.'),
  ('marine', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 3, 'In the variability calculator, a planner suspects that stormy weeks are also the heavy-cargo weeks. What does the engine do about that?', '["Nothing: it draws the weather and the demand independently, each from its stated triangular", "Links them by a stated correlation input, drawn through the canonical sampler", "It fits a joint distribution to past Ekene weeks and draws both factors from it", "It draws the demand factor from the weather draw, so a storm raises the cargo"]'::jsonb, 0, 'Each factor has its own uniform draw from the one mulberry32 stream, weather first, and no correlation is drawn between them. The engine fits no distribution to data. Correlation, fitting and distributions as a subject belong to the uncertainty course, which the course names once.'),
  ('marine', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 4, 'A planner wants the fleet plan discounted to a present value over three years. What does the engine return?', '["A discounted fuel bill at a stated rate, the one money figure the engine carries", "An NPV computed by the engine''s own discounting routine on the fuel cost alone", "No discounting at all: it computes no NPV, which belongs to the cash flow course", "A present value built from the vessel-days, discounted at the canonical rate"]'::jsonb, 2, 'The engine discounts nothing and computes no NPV; its one money figure is the fuel bill at the stated price. Discounting, NPV and a cash flow belong to Petroleum Economics and Cash Flow, and no rate is held anywhere in the engine.'),
  ('marine', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 5, 'Which course owns the stock levels, spares and reorder points of the cargo a supply vessel carries?', '["The materials course, Materials, Spares & Inventory Management; this engine takes the cargo as stated", "This course, whose fleet call keeps a reorder point for each bulk product on the vessel''s tanks", "The contracts course, Contract & Supplier Management, which sets the reorder point of each item", "The procurement course, Procurement, Tendering & Contracting, through the vessel''s charter terms"]'::jsonb, 0, 'The engine takes stated cargo and demand; stock levels, spares and reorder points are the subject of Materials, Spares & Inventory Management. The contracts course owns supplier performance and contract management, and the procurement course owns hiring the vessel.'),
  ('marine', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 6, 'The Ekene base is stated with 101 berths. What does the engine return, in its own words?', '["A result on 100 berths, the cap applied and noted in the basis", "berths must be a whole number from 1 to 100; got 101", "berths has 101 entries; the cap is 100", "A result on 101 berths with a note that the cap was passed"]'::jsonb, 1, 'MAX_BERTHS is 100, and the target search stops there too. The engine refuses 101 by name, verbatim as the key shows; it trims nothing to the cap, and an "entries" message belongs to a list such as the installations or the item lines.'),
  ('marine', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 7, 'A shore base call carries an unknown key queue and has no model stated. Which refusal does the engine return first?', '["model must be one of \"M/M/c\", \"M/D/c\"; got nothing, the missing input taken first", "Both refusals in one message, the missing model and the unknown key, in the order typed", "A result on M/M/c with the queue key dropped, since the key names a queue model the engine can already run for the base", "The unknown key queue, refused by name with the six keys the base reads; the missing model is refused after it"]'::jsonb, 3, 'Every function checks its accepted keys before it reads an input, so the unknown key is refused first, naming queue and listing the six top-level keys a base call reads. Fix it, and the missing model is refused next. The engine returns one refusal at a time and runs nothing on a box it refuses.'),
  ('marine', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 8, 'A deck plan call lists item lines whose quantities add to 2001 units. What does the engine return?', '["A plan of the first 2000 units, the last one listed as overflow", "items has 2001 entries; the cap is 500, the item-line cap", "items hold 2001 units in all; the cap is 2000", "items[0].quantity must be a whole number from 1 to 1000"]'::jsonb, 2, 'MAX_UNITS is 2000: the item lines times their quantities may not pass it, and the engine refuses the call in its own words as the key shows. The 500 cap is on item lines and the 1000 cap on one line''s quantity; neither is the limit this call breaks, and nothing is planned on a refused call.'),
  ('marine', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 9, 'Why does the engine refuse 181819 draws on a Monte Carlo with 11 voyage sets, when 200000 draws are allowed on a milk run?', '["200000 draws are allowed only on a milk run, and a dedicated route is capped at 181818", "Draws times voyage sets are capped at 2000000, since every draw sizes every set", "Each voyage set needs its own seed, and the seeds run out after 181818 draws on 11 sets", "The cap of 200000 is shared out among the sets, leaving 181818 draws for the largest"]'::jsonb, 1, 'Two caps work together: iterations up to 200000, and iterations times voyage sets up to 2000000. With 11 sets the most draws is 181818, and the engine says so, verbatim: "iterations must be at most 181818 with 11 voyage sets (iterations x voyage sets is capped at 2000000); got 181819". A milk run is one set, so the first cap binds there.'),
  ('marine', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 10, 'Which two modules does the marine logistics engine import, and what else does it reach?', '["lib/stats/stats.js and lib/conventions/percentile.js, and nothing else: no network call", "lib/stats/stats.js alone, with its own percentile code written for the fleet summaries", "The cash flow engine for its npv and lib/stats for its sampler, and a weather service online", "lib/conventions/percentile.js and a vendored copy of the inventory engine for the spares"]'::jsonb, 0, 'Its closure is two canonical files: lib/stats/stats.js, which gives it the seeded stream, the triangular inverse and the summaries, and lib/conventions/percentile.js, which gives it the exceedance sentence. Nothing else is imported, nothing goes over a network, and neither percentile code nor NPV lives in the engine.'),
  ('marine', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 11, 'What shape does the engine return when it refuses a call?', '["A thrown exception carrying a stack trace, which the calculator panel catches and prints", "A result object whose figures are all zero, with a reasons list naming the bad input", "An object with error and field, the message starting with the name of the field it refuses", "Code numbers from a table of refusals, which the panel then looks up and translates"]'::jsonb, 2, 'Every function returns either a result object or an object with error and field, where field names the input it refused and the message starts with that name and states the condition that failed. A refusal carries no figures; a result with a reason, such as a berth target no count meets, is a result.'),
  ('marine', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 12, 'A base has a berth with a bigger crane, hoses that reach one quay only and a rig vessel that jumps the queue. How does the engine model those?', '["Through berth-specific service rates, one stated for each berth in a list under service", "As a priority class for the rig vessel, served ahead of the others by a stated rule", "As a separate queue for each quay, the vessels routed by the stated hose reach", "It does not: the base is one queue of identical berths on the working-hour clock"]'::jsonb, 3, 'The engine knows no berth-specific cranes, shifts or priorities: it runs one queue with identical berths on the working-hour clock, under M/M/c or M/D/c. Each of those details makes a real base differ from both models, which is why a plan states the model and compares the two the engine offers.'),
  ('marine', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 13, 'What is the Marine Logistics Planner, and does a learner need it to finish this course?', '["The Suite app that runs this same engine file; the course is complete without it", "A separate engine in the Suite whose figures differ, so the course checks both against each other", "The Suite app that grades the capstone, so each learner must open it to finish the course", "A panel inside the course that replaces the four calculators for Suite users"]'::jsonb, 0, 'The Marine Logistics Planner, in the Suite''s Midstream & Downstream module, runs the same engine file in six tabs on the same Ekene fixture. The course''s own four calculator panels call the vendored engine, so every exercise and the capstone run without a Suite seat.'),
  ('marine', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 14, 'A logistics plan quotes the Monte Carlo of the Ekene week. What must it state beside each sampled figure?', '["Its tolerance, the band within which the capstone would accept it as a graded answer", "Its seed and its draws, 20260927 and 20000 here, and that it is an estimate", "Its confidence interval, which the engine returns beside every percentile it prints", "The number of vessels only, since vessel-days are too noisy to quote from the draws"]'::jsonb, 1, 'A Monte Carlo figure moves with its seed, so the plan quotes every one with its seed and draws and calls it an estimate; no sampled figure is graded, so none has a tolerance. The engine returns the mean, P90, P50, P10, min and max, and no confidence interval.'),
  ('marine', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 15, 'A voyage plan needs fuel at a slower, cheaper speed. What does the engine take in place of a speed and fuel curve?', '["A cubic law of speed built into the engine, scaling the burn at any speed typed", "The Skoko et al. burns held as the engine''s standing figures for every vessel", "A curve fitted to past voyages of the stated vessel, read at the speed typed", "A stated burn for each activity at the one stated speed, times the hours in it"]'::jsonb, 3, 'The engine computes fuel as the hours in each activity times the stated tonnes an hour, at the one stated speed: no speed and fuel curve is in it. The Skoko et al. burns are a published check the engine reproduces, and every burn is a required input.'),
  ('marine', 'advanced', 'final', null, 1, 'Lifts take 5.000000 hours and bulk 6.000000 hours on an Ekene call, run side by side. Which term decides how long the call runs beyond its fixed part?', '["The lifts, at 5.000000 hours, since the crane always leads", "Both together, 11 hours, since the two terms are always summed", "The bulk, at 6.000000 hours against 5.000000 for the lifts", "Neither, since alongside means the fixed hours set the call"]'::jsonb, 2, 'Side by side, only the longer of the two working terms counts toward the berth time, so the pumping governs here and the whole call comes to 8.000000 hours with its 2 fixed hours. Summing the pair belongs to calls stated as one after the other; the crane leads nothing by rule, and the fixed part is added in both cases.'),
  ('marine', 'advanced', 'final', null, 2, 'The Ekene base''s calls are restated with the lifts and the bulk one after the other, every other input held. By how much does a call lengthen, and at what berth utilisation do the berths then run?', '["By 5.000000 hours, to 13.000000, with the berths at 0.866667", "By 6.000000 hours, to 14.000000, with the berths at 0.866667", "By 0 hours, the call held at 8.000000, the berths at 0.533333", "By 3.180124 hours, the M/M/c wait added, the berths at 0.533333"]'::jsonb, 0, 'Concurrent false adds both terms: 2 plus 5 plus 6 is 13.000000 hours against 8.000000 alongside, 5.000000 hours more, which is the lift hours now added, and the berths then run at 0.866667. Adding the 6 bulk hours to the 8.000000 counts the bulk twice; holding the call at 8.000000 ignores the change; 3.180124 is the M/M/c wait of the concurrent base, a time in the queue.'),
  ('marine', 'advanced', 'final', null, 3, 'The shore base calculator prints the mean wait in hours and again in working days. How is the second figure made from the first?', '["Wait hours over 24, whatever the working day", "The wait in hours times the arrivals a day at the base", "The wait in hours over the service time of one call", "Hours divided by the stated length of one working day"]'::jsonb, 3, 'Every time the queue returns is on the working-hour clock, so a working day holds the stated working hours: the wait in working days is the wait in hours over the working hours a day. Dividing by 24 would count hours the base is closed; the other two are no conversion of a time at all.'),
  ('marine', 'advanced', 'final', null, 4, 'What condition must a shore base call meet before the engine returns any queue figure, and what happens when it fails?', '["A berth utilisation of at most 1; above it the engine returns the figures with a reason saying the base is overloaded", "A berth utilisation strictly below 1; at or above it the engine refuses and prints the most arrivals a day it accepts", "A mean wait under one working day; above it the engine refuses and prints the berths that would bring the wait down", "A probability of waiting below 0.5; above it the engine returns the figures and flags the base as one to be expanded"]'::jsonb, 1, 'At a berth utilisation of 1 or more the queue grows without limit and no steady state exists, so the engine refuses on arrivalsPerDay and prints the largest arrivals a day that stay below saturation. The berth target is a separate, optional search, and no wait or probability threshold stops a call.'),
  ('marine', 'advanced', 'final', null, 5, 'Iversen''s handbook counts offered traffic in erlangs. How many erlangs reach the two-berth Ekene quay in the engine''s return?', '["0.533333 erlang: the share of each berth''s hours that is spent busy", "1.066667 erlang: a little more than one berth kept busy on average", "3.2 erlang: one for each vessel that arrives in a working day", "2.000000 erlang: one for each berth, whatever the arrivals are"]'::jsonb, 1, 'An erlang is a berth-hour of work arriving each hour, so the offered load of 0.133333 arrivals an hour times 8.000000 service hours is 1.066667 erlang. 0.533333 is that load spread over the 2 berths; 3.2 is the arrivals a day; the berths bound the load from above and do not set it.'),
  ('marine', 'advanced', 'final', null, 6, 'Of the inputs a shoreBase call reads, which one may be left out without a refusal?', '["The working hours a day, which the engine takes as 24 when none is typed", "The concurrent choice, which the engine reads as one after the other if unstated", "The queue model, which the engine runs as M/M/c when the call does not name one", "The target mean wait, its one optional input; everything else is required"]'::jsonb, 3, 'The berths, the arrivals a day, the working day, every service term, the concurrent choice and the queue model are required, each refused by name when missing; the target mean wait is optional, and with it the engine adds the berth search. Nothing missing is filled in for the planner.'),
  ('marine', 'advanced', 'final', null, 7, 'Which sentence about the Ekene base follows the course''s vocabulary?', '["The berth utilisation is 0.533333 and the wait, time in the queue, is 3.180124 hours as M/M/c", "The utilisation is 0.533333, so vessels wait for a berth about half of the time they are at the base", "The wait of a vessel is 11.180124 hours as M/M/c, counting its time alongside the berth as well", "The capacity of the base is 3 arrivals a day, which is its berth utilisation read in arrivals"]'::jsonb, 0, 'Utilisation is always of a named thing, here the berths, and the wait is the mean wait in the queue on the working-hour clock; the time at the base (11.180124 hours) adds the service. A capacity is always of a named constraint, and a berth utilisation says nothing about the share of time spent waiting.'),
  ('marine', 'advanced', 'final', null, 8, 'Ten servers at an occupation of 0.9 with a mean service of 1: Adan and Resing (Queueing Systems, 26 March 2015) print 0.67 as the wait. What does the engine give?', '["0.67 exactly, a figure taken from the printed row", "1.524986, the engine''s wait at five servers", "0.668732, rounded by the table to 0.67", "0.275385, the engine''s wait at twenty servers"]'::jsonb, 2, 'The golden call behind that row states 90 arrivals over a 10-hour day and 1 fixed hour, so ten berths sit at 0.900000; eq. 5.3 then gives 0.668732, and two-decimal rounding reproduces the table''s 0.67. Other rows give 1.524986 (five servers, where the table''s 1.53 is a slip) and 0.275385 (twenty).'),
  ('marine', 'advanced', 'final', null, 9, 'At one server in Adan and Resing''s Table 5.1, with an occupation rate of 0.9 and a mean service of 1, which two figures does the engine return?', '["0.900000 as the chance of waiting, 9.000000 as the mean wait", "The two-server pair, 0.852632 and 4.263158", "0.900000 as the chance of waiting, but only 4.500000 as the mean wait", "1.000000 as the chance of waiting, with 9.000000 again as the mean wait"]'::jsonb, 0, 'At one server the delay probability of M/M/1 is the occupation rate, 0.900000, and the mean wait is 9.000000, both matching the printed 0.90 and 9.00. 0.852632 and 4.263158 are the two-server row; 4.500000 is the M/D/1 wait at the same load; a delay probability of 1 would mean saturation.'),
  ('marine', 'advanced', 'final', null, 10, 'Iversen''s first delay system (Teletraffic Engineering Handbook, draft of 20 June 2001) has 32 channels, a mean service of 100 and 20 erlang. What does the engine return for it?', '["An offered load of 2.000000, a delay probability of 0.059701 and a mean wait of 0.199005", "An offered load of 20.000000, a delay probability of 0.008964 and a mean wait of 0.075 exactly", "An offered load of 20.000000, a delay probability of 0.008964 and a mean wait of 0.074697", "An offered load of 20.000000, a delay probability of 0.059701 and a mean wait of 0.273702"]'::jsonb, 2, 'On the golden inputs (a fixed service of 100, 32 berths, 2 arrivals a day over a 10-hour day) the engine returns 20.000000, 0.008964 and 0.074697, and the wait rounds to the printed 0.075. The second system''s figures are 2.000000, 0.059701 and 0.199005; 0.273702 is the two waits added.'),
  ('marine', 'advanced', 'final', null, 11, 'At the same occupation of 0.9, Adan and Resing''s Table 5.1 waits 9.000000 at one server and 0.275385 at twenty. What does that teach a base planner?', '["Twenty berths are always cheaper to run than one, whatever the arrivals are", "That the occupation rate is a poor measure, since it gives the same figure twice", "That the table''s larger rows are slips, since a wait cannot fall that far that fast", "Pooling: one queue shared across many berths waits far less at the same occupation"]'::jsonb, 3, 'Held at the same occupation, twenty servers on one queue wait a small fraction of what one server waits, because it takes many vessels at once to fill every berth. The engine prices no berth, the occupation still says whether a steady state exists and how busy the berths are, and every figure in the row checks against the engine.'),
  ('marine', 'advanced', 'final', null, 12, 'Three berths at the Ekene quay cut the M/M/c wait to 0.440347 hours. By Little''s law, how many vessels queue on average?', '["0.106417 vessels, the probability of waiting read across as a count", "0.058713 vessels, the arrivals an hour times that wait, by Little''s law", "0.355556 vessels, the berth utilisation of the three berths", "0.424017 vessels, since the length of the queue is set by the arrivals alone"]'::jsonb, 1, '0.133333 arrivals an hour times 0.440347 hours gives the engine''s mean queue of 0.058713 to the precision printed; eq. 5.2 gives the same figure from the probability of waiting. 0.424017 is the two-berth mean queue; the queue shrinks with the third berth although the arrivals have not moved.'),
  ('marine', 'advanced', 'final', null, 13, 'Stated with 5 berths, the Ekene base as M/M/c returns a mean time at the base of 8.010236 hours. Why can more berths never take it below 8.000000?', '["Because 8.000000 hours is the least wait the engine reports at any number of berths", "The engine caps the berths at five for the Ekene base, so the time stops there", "Because the mean in the system cannot fall below the 8.000000 berths of the Ekene base", "Every vessel is served, and the 8.000000-hour service is part of its time at the base"]'::jsonb, 3, 'The time at the base is the wait plus the service, so as the wait falls toward nothing (0.010236 hours at five berths) the time falls toward the service of 8.000000 hours and no lower. The berth cap is 100, the base has 2 berths as stated, and the mean in the system is a count of vessels.'),
  ('marine', 'advanced', 'final', null, 14, 'What does M/M/c assume about the vessels arriving at a base and the calls they make?', '["Evenly spaced arrivals, a constant service time, one queue per berth, served in order of cargo size", "Poisson arrivals, exponential service times, one queue served first come first served, in a steady state", "Poisson arrivals, a constant service time, one queue served first come first served, in a steady state", "Scheduled arrivals, exponential service times, priority to the rig vessels, over one working day"]'::jsonb, 1, 'The two Ms are Poisson arrivals and exponential service, and c berths serve one queue first come first served in a steady state. Poisson arrivals with a constant service is M/D/c; the engine holds no schedule, no per-berth queue and no priority.'),
  ('marine', 'advanced', 'final', null, 15, 'Why does the engine keep the word approximation on its M/D/c wait at two berths while the one-berth figure checks exactly?', '["At two berths the engine simulates the queue, so its figure carries the noise of a seeded Monte Carlo of arrivals", "At two berths the formula drops its correction term, so only half of the M/M/c wait is used and some is lost", "At one berth the formula becomes the exact Pollaczek-Khinchin result; at several berths no exact formula exists to check it", "At one berth the engine switches to M/M/c, and the word approximation is kept for the M/D/c branch alone"]'::jsonb, 2, 'Liu et al. (arXiv 2102.05851v2) state that M/D/c has no closed form for its mean wait, and the engine uses the Cosmetatos approximation, which reduces to the Pollaczek-Khinchin formula at c = 1. The engine simulates no queue; the correction vanishes only at one berth; and the model stated is the model run.'),
  ('marine', 'advanced', 'final', null, 16, 'In the Cosmetatos correction, (1 - rho)(c - 1)(sqrt(4 + 5c) - 2) / (16 rho c), what happens to the correction as the berths get busier at a fixed berth count?', '["It shrinks, since (1 - rho) falls and rho sits in the denominator", "It grows, since a busier base needs a larger correction to its wait", "It stays fixed, since the correction depends on the berths alone", "It turns negative once rho passes one half, pulling the wait down"]'::jsonb, 0, 'As rho rises, the factor (1 - rho) falls and the denominator 16 rho c rises, so the correction shrinks and the M/D/c wait moves toward half the M/M/c wait. For rho below 1 and c at least 1 no term is negative, so the correction never pulls the wait below half.'),
  ('marine', 'advanced', 'final', null, 17, 'Across the cases the course runs, where does the engine''s M/D/c wait sit against half the M/M/c wait on the same inputs?', '["Below half at every berth count, since constant service removes most of the wait", "At or above half: exactly half at one berth, a little above it at two or three", "Exactly half at every berth count, since the correction never changes the figure", "Above the whole M/M/c wait at three berths, since the correction grows with c"]'::jsonb, 1, 'At one berth the correction is zero and the M/D/1 wait is half the M/M/1 wait (4.500000 against 9.000000). At two berths the Ekene ratio is 0.523812, and at three berths 0.552578 (the Cosmetatos approximation) against 1.078652 is again a little over half. The correction is never negative, so the wait is never below half.'),
  ('marine', 'advanced', 'final', null, 18, 'Which formula gives the M/D/c wait at one berth, where the engine''s approximation is exact?', '["rho S / (2 (1 - rho)), the Pollaczek-Khinchin mean value formula for M/D/1", "PiW S / (c (1 - rho)), eq. 5.3 of Adan and Resing, taken with c = 1 in it", "rho S / (1 - rho), the M/M/1 wait, since one berth leaves nothing to correct", "S / (2 (1 - rho)), the service over twice the idle share, with no rho on top"]'::jsonb, 0, 'At one berth the correction vanishes and the wait is half the M/M/1 wait, rho S / (2 (1 - rho)): Adan and Resing, s. 7.6, eqs 7.14 to 7.16. On one berth at 0.900000 with a 1-hour service it gives 4.500000, as the engine returns. rho S / (1 - rho) is the M/M/1 wait, twice as long, and eq. 5.3 is the M/M/c formula.'),
  ('marine', 'advanced', 'final', null, 19, 'Asked for a general-service queue, a planner types M/G/c as the model. Which message comes back?', '["A result by the Pollaczek-Khinchin formula for a general service", "A result as M/M/c, the nearest model it offers, with a note", "model must be one of \"M/M/c\", \"M/D/c\"; got \"M/G/c\"", "model is not an accepted key; the accepted keys are the models"]'::jsonb, 2, 'The engine offers two queue models and refuses any other by name, verbatim as the key shows; a call with no model is refused the same way, ending "got nothing". It maps no model to a neighbour and runs no general-service formula.'),
  ('marine', 'advanced', 'final', null, 20, 'A base''s calls are much the same length every time. Which queue model sits closer to it, and which figure suits a plan that must not understate the wait?', '["M/M/c sits closer, since any real call varies, and its figure is also the one that understates the wait", "M/D/c sits closer, and its figure is the safe one to quote, being the longer wait of the two models", "Neither model applies to calls of fixed length, so the engine refuses such a base as a matter of rule", "M/D/c sits closer; a plan that must not understate the wait can quote the M/M/c figure, model named"]'::jsonb, 3, 'Constant service is the D of M/D/c, so a base of like calls is closer to it; a real base sits between the two models. The M/D/c wait (the Cosmetatos approximation) is the shorter (1.665786 hours against 3.180124 on the Ekene quay), so the M/M/c figure is the one that does not understate, quoted with its model named. The engine refuses no base for its service spread.'),
  ('marine', 'advanced', 'final', null, 21, 'A planner wants the Ekene quay''s mean wait held to 0.3 hours or less. What does the berth search return under each queue model, M/D/c being the Cosmetatos approximation?', '["3 berths under both models, at 0.440347 hours as M/M/c and 0.259397 hours as M/D/c", "4 berths under both models, the M/D/c wait at four berths being lower still", "4 berths under M/M/c at 0.068902 hours, and 3 under M/D/c at 0.259397", "2 berths under M/D/c, its wait being about half the M/M/c one"]'::jsonb, 2, 'Under M/M/c three berths wait 0.440347 hours, above the target, so the search goes on to four, which wait 0.068902. Under M/D/c (the Cosmetatos approximation) three berths already wait 0.259397, inside it. Two berths wait 1.665786 hours as M/D/c, far above. The search runs the model the call states, and here the model changes the count.'),
  ('marine', 'advanced', 'final', null, 22, 'How are the Ekene week''s 20000 draws on seed 20260927 spread over whole vessels?', '["2 vessels in every draw, since the plan at the modes needs 2 of them", "3 vessels in 0.085000 of the draws, the rest of the draws needing 2 vessels", "2 vessels in 0.500000 of the draws and 3 vessels in all the rest of them", "2 vessels in 0.998600 of the draws and 3 in 0.001400, both estimates"]'::jsonb, 3, 'Each draw rounds its vessel-days over 6.5 available days up to whole vessels: on seed 20260927 and 20000 draws, 0.998600 need 2 and 0.001400 need 3. 0.085000 is the AHTS dedicated run''s probability short (seed 11, 5000 draws). The plan at the modes is one week, and the draws spread around it.'),
  ('marine', 'advanced', 'final', null, 23, 'Why do the Ekene week''s sampled vessel-days come in steps, without spreading smoothly between them?', '["The triangular inverse CDF returns only a few distinct values from the stream of uniform numbers", "Each draw rounds its voyages up to whole voyages, so the requirement moves a voyage at a time", "Every vessel-day figure is rounded to a whole day before the draws are summarised", "The seed of 20260927 happens to fall on a pattern, and another seed would give a smooth spread"]'::jsonb, 1, 'Every draw sizes the fleet as fleetSize does, with voyages rounded up, so the vessel-days jump by one voyage''s days; in light weeks the minimum visits hold the count up. The triangular gives a continuous spread, no vessel-day figure is rounded to a day, and any seed shows the steps.'),
  ('marine', 'advanced', 'final', null, 24, 'A fleetVariability call runs the Ekene inputs for 1 draw on seed 0. What does the engine return, and what does it show?', '["7.648544 vessel-days as the mean, the P90 and the P10 alike: one sized week that summarises nothing", "10.345455 vessel-days, since one draw falls back on the plan at the modes of the week", "A refusal, since a Monte Carlo needs at least 2 draws to form a P90 and a P10 at all", "7.648544 vessel-days as the P90 and 10.345455 as the P10, the draw and the plan side by side"]'::jsonb, 0, 'One draw is a single sized week: on seed 0 it returns 7.648544 vessel-days as its mean, P90 and P10. The draws run from 1 to 200000, so one draw is accepted; more draws steady an estimate and cost time. The plan at the modes is reported beside it and is no draw.'),
  ('marine', 'advanced', 'final', null, 25, 'With the weather alone varying (triangular 1, 1.2, 1.6; seed 3, 3000 draws), the engine''s mean vessel-days come out above the plan at the modes. Why that direction?', '["The triangular''s long side runs up to 1.6, so its average lies above its mode of 1.2", "The weather factor is drawn first, and the first draw of a stream always runs high on its seed", "A seed of 3 is a low seed, and low seeds give draws that sit above the mode of a triangular", "The demand factor, held at 1, is raised by the engine to match the weather"]'::jsonb, 0, 'On seed 3 and 3000 draws the mean is 10.803806 against the plan''s 10.345455. A triangular from 1 to 1.6 with its mode at 1.2 has its average above 1.2, so the sampled weeks run longer on average than the week at the mode. The draw order fixes which uniform number goes where and biases nothing; a fixed factor stays fixed.'),
  ('marine', 'advanced', 'final', null, 26, 'The Ekene inputs are run with 0 planned vessels (seed 9, 500 draws). What probability short does the engine return?', '["0.000000, since with no planned vessels no shortfall can be measured against a planned fleet", "A refusal, since the planned vessels must be at least 1 for the chance of being short to be measured", "0.001400, the Ekene week''s figure, since the planned vessels do not enter the draws", "1.000000, every draw short by its whole requirement, since there is no planned capacity"]'::jsonb, 3, 'The planned vessels run from 0 to 1000, so 0 is accepted; the planned capacity is then 0 vessel-days, and every draw needs more, so the engine returns a probability short of 1.000000 on seed 9 and 500 draws, each draw short by its whole requirement. 0.001400 is the two-vessel Ekene week on seed 20260927.'),
  ('marine', 'advanced', 'final', null, 27, 'A fleetVariability call asks for 200001 draws on the Ekene milk run. What does the engine return?', '["A result on 200000 draws, the cap applied with a note of the trim in the basis", "Refused on iterations, since the draws run from 1 to 200000 and this is one over", "iterations must be at most 181818 with 1 voyage set; got 200001", "A result on 200001 draws, since a milk run has only one voyage set to size in each draw"]'::jsonb, 1, 'MAX_ITERATIONS is 200000, and the engine refuses 200001 by name, verbatim: "iterations must be a whole number from 1 to 200000; got 200001". The 181818 figure is the draws cap for 11 voyage sets; a milk run is one set, so the iterations cap binds first. The engine trims nothing to a cap.'),
  ('marine', 'advanced', 'final', null, 28, 'On seed 11 and 5000 draws, the AHTS on dedicated voyages is short in 0.085000 of its draws with 2 planned vessels. What does that say against the PSV milk run''s 0.001400 on seed 20260927 and 20000 draws?', '["The AHTS figure is the exact probability and the PSV figure only an estimate", "The two are equal once the draws are matched, since both weeks plan 2 vessels", "The same two vessels leave a thinner margin on the AHTS week, as estimates", "The AHTS needs a third vessel in every week, since any shortfall means that"]'::jsonb, 2, 'Both are seeded estimates on their own seeds and draws, and neither is graded. With the same 2 planned vessels, the AHTS on dedicated voyages is short far more often than the PSV milk run, a thinner margin; neither figure says a third vessel is needed every week, and matching draws would not make them equal.'),
  ('marine', 'advanced', 'final', null, 29, 'Why does no capstone field in this course depend on one of the readings the engine states?', '["Capstones are graded with a tolerance wide enough to cover any change of reading", "The readings apply only to the Monte Carlo, and no capstone field is a sampled figure", "The capstones run the engine''s alternative readings, so that learners cannot rely on them", "Each capstone field is the same number under every reading and under the alternative named beside it"]'::jsonb, 3, 'The capstones were built so that every graded figure is identical under each reading the engine takes and under the alternative it names; the readings are taught with their alternatives and graded nowhere. Most readings act on voyages, fleets, decks and berth targets, far beyond the Monte Carlo, and the tolerance is set once for the course.'),
  ('marine', 'advanced', 'final', null, 30, 'Deck area and deck load share a utilisation of 0.500000 on a voyage, and every other constraint sits lower. Which constraint does the engine name as binding, and on what footing?', '["Deck area, the first in the stated order, by the engine''s stated tie reading", "Deck load, the last of the tied pair, since the heavier limit governs any tie", "Both at once, since a tie at twelve digits names every tied constraint", "Neither, since a tie leaves the voyage with no binding constraint at all"]'::jsonb, 0, 'A binding tie at twelve significant digits goes to the first constraint in the order deck area, deck load, deadweight, then the tanks, so the engine names deck area. That is its stated reading; the alternative it names gives the tie to the last of the tied constraints, deck load here.'),
  ('marine', 'advanced', 'final', null, 31, 'A deck plan holds a unit that fills the usable deck of a voyage exactly. What does the engine do with it?', '["Lists it as overflow, since a unit must leave some room to be stowed safely on the deck", "Carries it: an exact fill fits, on the engine''s stated reading, and nothing overflows", "Refuses the call, since a unit may not be as large as the usable area of the deck it sails on", "Lists it in neverFit, since it cannot share the voyage with any other unit"]'::jsonb, 1, 'On the engine''s reading an exact fill fits: on its exact-fit case 2 units are carried and 0 overflow. The alternative reads an exact fill as overflow. neverFit holds units larger than the usable area or heavier than the deck load, and a unit that fits an empty voyage is carried.'),
  ('marine', 'advanced', 'final', null, 32, 'When does the engine add "(rounded down at the sixth decimal so that it is accepted)" to a printed bound in a refusal?', '["Every time it prints a bound, whether or not it moved the figure at all", "Only when the exact bound is a whole number, such as 20 arrivals a day", "Only when the printed six-decimal figure differs from the exact bound", "Only when the arrivals typed were more than twice the exact bound itself"]'::jsonb, 2, 'The note marks a moved figure. Where the true limit is 20, that limit is itself refused, so 19.999999 appears with the note; where it repeats, the usual six-decimal rounding would land above it, so the message moves down a step and says so.'),
  ('marine', 'advanced', 'final', null, 33, 'How does the five-server row of Adan and Resing''s Table 5.1 check against itself, confirming the printed 1.53 as a slip?', '["Eq. 5.2 on the row''s mean queue gives 1.53 exactly, so the slip is in the delay probability printed", "Eq. 5.3 on the row''s own delay probability, 0.762493, gives 1.524986, and the printed 0.76 gives 1.52", "The row''s delay probability is misprinted too, and the misprinted value gives the printed wait of 1.53", "The rows of Table 5.2 at five servers print 1.53 as well, which confirms the Table 5.1 figure"]'::jsonb, 1, 'At a mean service of 1, eq. 5.3 divides the delay probability by five servers times the idle share of 0.1: 0.762493 gives 1.524986, and even the printed 0.76 gives 1.52. The row''s delay probability rounds to the printed 0.76, and Table 5.2''s five-server wait is 9.503169, printed 9.50.'),
  ('marine', 'advanced', 'final', null, 34, 'How does the course use Aas, Halskau and Wallace (Maritime Economics & Logistics 11(3), 302-325, 2009)?', '["By quoting its fleet-sizing example, whose printed vessel count the engine reproduces as a published check", "By table and equation, since it is CC BY 4.0 like Skoko et al. and the arXiv paper on M/D/c queues", "By concept only, since it is publisher copyright: deck cargo in m2 with no stacking, bulk in segregated tanks", "As the source of the queue models, from which the engine takes Erlang''s C formula for the shore base"]'::jsonb, 2, 'The paper is publisher copyright and was read as the accepted manuscript, so the course teaches its ideas by concept and quotes none of its prose. No openly readable paper printed a fleet-sizing example with a vessel count; the CC BY 4.0 texts are Skoko et al. and the arXiv paper, and Erlang''s C formula comes from Adan and Resing and Iversen.'),
  ('marine', 'advanced', 'final', null, 35, 'A fleet call states a period of 7 days and 7.5 available days a vessel. What does the engine return?', '["vesselAvailableDays must be at most periodDays (7); got 7.5", "A result with the available days cut to 7 and a note of the cut", "A result on 7.5 available days, the extra half day spare", "periodDays must be a finite number above 0; got 7"]'::jsonb, 0, 'Available days equal to the period are accepted and anything above it is refused by name, verbatim as the key shows: a vessel cannot be available for more days than the period holds. The engine trims nothing, and the period itself is valid.'),
  ('marine', 'advanced', 'final', null, 36, 'Which names does the marine logistics engine export, in full?', '["deckPlan, fleetSize, fleetVariability, shoreBase and voyagePlan, and no constants at all", "ACTIVITIES, DEFAULTS, deckPlan, fleetSize, npv, shoreBase, voyagePlan and a sampler of its own", "ACCEPTED_KEYS, DEFAULTS, deckPlan, fleetSize, shoreBase, voyagePlan and a schedule builder", "ACCEPTED_KEYS, ACTIVITIES, DEFAULTS, deckPlan, fleetSize, fleetVariability, shoreBase, voyagePlan"]'::jsonb, 3, 'The engine exports its five functions, the accepted keys of each, the three activities and the DEFAULTS that hold its caps and the tie rule. It computes no NPV, carries no sampler of its own and builds no schedule by the clock.'),
  ('marine', 'advanced', 'final', null, 37, 'What does every result the engine returns carry, so that its working can be printed?', '["A basis block naming the rules it applied and the sources they come from", "A confidence band around each figure, set by the stated usable deck fraction", "A timestamp and machine tag, so that two runs can be told apart later", "A list of the defaults it filled in for every input the call left out"]'::jsonb, 0, 'Every result carries a basis naming its rules and where they come from, in the engine''s own words; voyagePlan and fleetSize also return reasons, and a shoreBase target returns its own reason. It reads no clock, holds no figure for a missing input (a missing input is refused by name) and prints no confidence band.'),
  ('marine', 'advanced', 'final', null, 38, 'How many item lines may one deckPlan call carry, and what happens to a call with 501 of them?', '["At most 2000, the units cap, so 501 lines are accepted and planned", "A plan of the first 500 lines, with the one line left over listed as overflow", "At most 500; the call is refused with \"voyages must be a whole number from 1 to 500; got 501\"", "At most 500; the call is refused with \"items has 501 entries; the cap is 500\""]'::jsonb, 3, 'MAX_ITEM_LINES is 500, and the engine refuses 501 lines in the words the key quotes. The 2000 cap counts units across all the lines, and the voyages cap, also 500, belongs to the voyages input. A refused call plans nothing, so no line is carried or listed as overflow.'),
  ('marine', 'advanced', 'final', null, 39, 'A deck foreman asks the engine whether a load can be stacked two high and lashed in lanes. What does the engine take in place of that?', '["Stacking factors for each item, stated on the line with its footprint and weight", "A lane plan built from the deck''s length and width, packed by first-fit decreasing", "An area bound with the stated usable fraction and deck load, and no stacking or deck shape", "A stability check on the stated deadweight, with the centre of gravity of the load"]'::jsonb, 2, 'The engine computes an area bound only: each unit''s footprint against the deck area times the usable fraction, and its weight against the deck load. Stacking, deck shape, lanes and stability are the deck foreman''s plan; an item carries only its id, name, length, width, weight and quantity.'),
  ('marine', 'advanced', 'final', null, 40, 'A planner adds a stowage factor to the deck terms of a deck plan call. What does the engine return?', '["A plan with the usable area scaled by the stowage factor, and the factor printed in the basis of the plan", "deck.stowageFactor is not an accepted key; the accepted keys of deck are name, areaM2, usableFraction, loadT", "A plan that ignores the factor quietly, since the usable fraction already covers the stowage of the deck", "deck.usableFraction must be a number above 0 and at most 1; got nothing"]'::jsonb, 1, 'The engine holds no stowage factor: for the deck it takes an area bound with a stated usable fraction and deck load, and for bulk the user''s net deadweight and stated densities. An unknown key is refused by name with the accepted keys, verbatim as the key shows; nothing is dropped quietly. The usable fraction message belongs to a deck call with that input left out.'),
  ('marine', 'advanced', 'final', null, 41, 'The Ekene base waits 3.180124 hours as M/M/c. Which claim can a plan rest on that figure?', '["That a vessel arriving at dawn on Tuesday will be alongside a berth by the middle of the morning", "That no vessel at the base will ever wait longer than 3.180124 hours in the queue for a berth", "That the base will need no third berth in any week, whatever the arrivals turn out to be", "That 2 berths give a steady-state mean wait of about three hours under M/M/c on the stated inputs"]'::jsonb, 3, 'A queue figure is a steady-state average of a stated model on stated inputs. It supports a berth count on those inputs; it is no timetable, no bound on any single wait and no forecast of a week''s arrivals, since the engine plans no schedule by the clock.'),
  ('marine', 'advanced', 'final', null, 42, 'Which course of the academy owns supplier performance and contract management around the supply vessels?', '["The contracts course, Contract & Supplier Management; this engine takes nothing on it", "This course, whose fleet call scores each vessel operator on the voyages it delivered in the period", "The materials course, which rates suppliers by the spares they deliver on each voyage", "The uncertainty course, since supplier performance is a distribution to be sampled by Monte Carlo"]'::jsonb, 0, 'Supplier performance and contract management are the subject of Contract & Supplier Management, and the engine takes no input for them. The materials course owns stock and spares; the uncertainty course owns Monte Carlo as a subject; the fleet call scores no operator.');
